// The Portuguese of What's new, what each version changed (lib/whats-new.ts, app/whats-new.tsx) (i18n/pt/index.ts).
export const whatsNew: Record<string, string> = {
  "What's new": 'Novidades',
  'What each version changed': 'O que mudou em cada versão',
  'What each version of Erevos changed, the newest first.': 'O que mudou em cada versão do Erevos, da mais nova para a mais antiga.',
  'Not out yet': 'Ainda não lançada',
  'This version': 'Esta versão',
  'For you': 'Para você',
  'Under the hood': 'Nos bastidores',
  // Not out yet.
  "**Links open on Sailfish OS**: **Sign in with LPHL**, a donation page or a link in a chat opened nothing there. Now Sailfish OS opens them: a web page in the browser, a number in the phone or the messages, an address in the mail.":
    "**Os links abrem no Sailfish OS**: **Entrar com LPHL**, uma página de doação ou um link numa conversa não abriam nada. Agora o Sailfish OS abre-os: uma página web no navegador, um número no telefone ou nas mensagens, um endereço no email.",
  "**Matrix, and photos and files in XMPP and Nostr chats, on Sailfish OS**: Erevos there could not reach their servers over HTTPS, so Matrix could not sign in, photos and files neither came nor went, and links showed no preview. Now they work as on a computer.":
    "**Matrix, e fotos e arquivos nas conversas XMPP e Nostr, no Sailfish OS**: lá o Erevos não alcançava os servidores deles por HTTPS, então o Matrix não conseguia entrar, fotos e arquivos não chegavam nem saíam e os links não mostravam prévia. Agora funcionam como num computador.",
  "**A phone call shows its screen**: with Erevos as the phone app, a call that came could ring with the phone's screen black, so it could not be answered, when Android's full-screen notifications for Erevos, Erevos's notices or its notices of incoming calls were off. Now the call screen comes up by itself, over the lock screen too, and turns the screen on. A call that Do Not Disturb holds back still comes quietly, with the screen off. See [Phone](#phone).":
    "**Uma chamada telefônica mostra a sua tela**: com o Erevos como app de telefone, uma chamada recebida podia tocar com a tela preta, sem poder ser atendida, quando estavam desativadas as notificações em tela cheia do Android para o Erevos, as notificações do Erevos ou as notificações dele de chamadas recebidas. Agora a tela de chamada aparece sozinha, também sobre a tela de bloqueio, e acende a tela. Uma chamada que o \"Não perturbe\" segura continua chegando em silêncio, com a tela apagada. Veja [Telefone](#phone).",
  "**The calculator shows a long result from its start**: upright, a result with many decimals hid its first digits, which showed only with the phone turned sideways. Now a long number gets smaller to fit, its first digits always in sight.":
    "**A calculadora mostra um resultado longo desde o início**: na vertical, um resultado com muitas casas decimais escondia os primeiros dígitos, que só apareciam com o telefone na horizontal. Agora um número longo fica menor até caber, com os primeiros dígitos sempre à vista.",
  "**Pick the recipient of a new SMS from your contacts**: **New SMS** has a **Contacts** button that opens your contacts with a search, and typing a name or number suggests the contacts that match. A contact with several numbers shows a line for each, and for a group MMS each one you pick is added. With only the SMS open, only the phone's contacts show. See [SMS](#sms).":
    "**Escolha o destinatário de um novo SMS entre os contatos**: **Novo SMS** tem um botão **Contatos** que abre seus contatos com busca, e ao digitar um nome ou número aparecem os contatos que combinam. Um contato com vários números mostra uma linha para cada um, e em um MMS em grupo cada contato escolhido é acrescentado. Com só os SMS abertos, aparecem só os contatos do telefone. Veja [SMS](#sms).",
  // 4.0.0-rc.10
  "**Erevos no longer stops when only the SMS or the Contacts are open**: from them, a contact's chat, an SMS, another icon or a screen that asks for the password again could make Erevos say it could not open (Maximum call stack size exceeded). Now the password opens all of Erevos, then that screen. And when Erevos cannot open, **Try again** starts it again. See [Password lock](#lock).":
    "**O Erevos não para mais quando só os SMS ou os contatos estão abertos**: a partir deles, a conversa de um contato, um SMS, outro ícone ou uma tela que pede a senha de novo podiam fazer o Erevos dizer que não conseguiu abrir (Maximum call stack size exceeded). Agora a senha abre todo o Erevos e depois essa tela. E quando o Erevos não consegue abrir, **Tentar de novo** o inicia outra vez. Veja [Bloqueio com senha](#lock).",
  "**Each icon opens what it names**: after Erevos was opened by the SMS icon, or from the recent apps, another icon, the widget or a notice could sometimes show the SMS instead. Now each opens what it names. With only the SMS or the Contacts open, another icon asks for the password as when Erevos is locked, then opens its own part: the Contacts icon only the contacts, Erevos's own icon all of it. And Back on Erevos's first screen now puts it behind, as Home does, whatever opened it. See [Password lock](#lock).":
    "**Cada ícone abre o que indica**: depois que o Erevos foi aberto pelo ícone de SMS ou a partir dos apps recentes, outro ícone, o widget ou um aviso podiam às vezes mostrar os SMS no lugar. Agora cada um abre o que indica. Quando só os SMS ou os contatos estão abertos, outro ícone pede a senha como quando o Erevos está bloqueado e depois abre a sua própria parte: o ícone de Contatos só os contatos, o ícone do próprio Erevos todo o Erevos. E Voltar na primeira tela do Erevos agora o deixa em segundo plano, como o botão de início, seja o que for que o abriu. Veja [Bloqueio com senha](#lock).",
  // 4.0.0-rc.9
  "**Only the Contacts**: with Erevos locked, the Contacts icon, the widget's Contacts button and the notice of a birthday ask for the password, then open only the contacts. A chat, an SMS, Settings, and the orange padlock **Unlock everything**, ask for it again, then open all of Erevos. See [Password lock](#lock).":
    "**Só os Contatos**: com o Erevos bloqueado, o ícone de Contatos, o botão Contatos do widget e o aviso de um aniversário pedem a senha e depois abrem só os contatos. Uma conversa, um SMS, as Configurações e o cadeado laranja **Desbloquear tudo** pedem a senha de novo e depois abrem todo o Erevos. Veja [Bloqueio com senha](#lock).",
  "**Old private messages in Nostr chats**: Erevos also reads private messages sent the older way (NIP-04), which Damus, Primal and many apps still send and keep, past and new, in the same chats. The relays see who wrote such a message to whom; Erevos itself still sends only the NIP-17 way. See [Chats with other Nostr apps](#nostr-chats).":
    "**Mensagens privadas antigas nas conversas Nostr**: o Erevos também lê as mensagens privadas mandadas do jeito antigo (NIP-04), que o Damus, o Primal e muitos apps ainda mandam e guardam: passadas e novas, nas mesmas conversas. Os relays veem quem escreveu uma mensagem dessas para quem; o próprio Erevos continua mandando só do jeito do NIP-17. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**Public posts in Nostr chats**: in a chat with one person, **Public posts** shows what they post for everyone, newest first, read only. It is looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Publicações públicas nas conversas Nostr**: numa conversa com uma pessoa, **Publicações públicas** mostra o que ela publica para todos, das mais recentes às mais antigas, somente leitura. Isso é buscado pelo Tor como o espaço diz e não é guardado, e nenhuma imagem ou link é aberto. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  // 4.0.0-rc.8
  // 4.0.0-rc.7
  "**Licence**: Settings → General → Licence says under which licence Erevos is free software, AGPL-3.0-or-later, its three additional terms, that it comes with no warranty, and who made it. See [Licence](#licence).":
    "**Licença**: Configurações → Geral → Licença diz sob qual licença o Erevos é software livre, AGPL-3.0-or-later, as suas três condições adicionais, que ele vem sem nenhuma garantia, e quem o fez. Veja [Licença](#licence).",
  "**Contact**: Settings → General → Contact adds the maker of Erevos as a contact, to write to in Erevos itself, end-to-end encrypted, with no phone number and no email. See [What Erevos is](#about).":
    "**Contato**: Configurações → Geral → Contato adiciona o criador do Erevos como contato, para você escrever para ele no próprio Erevos, com criptografia de ponta a ponta, sem número de telefone e sem e-mail. Veja [O que é o Erevos](#about).",
  "**A new sticker set, Angry Eyes**: 24 faces of big yellow eyes on a black disc, drawn by the maintainer, each with the moves he gave it.":
    "**Um novo conjunto de figurinhas, Angry Eyes**: 24 rostos de grandes olhos amarelos em um disco preto, desenhados pelo criador do Erevos, cada um com os movimentos que ele lhe deu.",
  "**The calculator opens again**: in 4.0.0-rc.6 it closed as soon as it was tapped.":
    "**A calculadora volta a abrir**: na 4.0.0-rc.6 ela fechava assim que você tocava nela.",
  "**People you follow on Nostr are looked for on more relays**: **Show the people you follow** also asks relays that gather follow lists and more of the relays your key writes on, and waits longer for them; when it finds no one, it says why and how each relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**As pessoas que você segue no Nostr são procuradas em mais relays**: **Mostrar as pessoas que você segue** consulta também relays que reúnem listas de seguidos e mais dos relays onde a sua chave escreve, e espera mais tempo por eles; quando não encontra ninguém, diz por quê e como cada relay respondeu. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  // 4.0.0-rc.6
  "**Panic password**: with the password lock on, **Set the panic password** under the Panic button sets a password of its own that, typed on the lock screen, wipes Erevos as **Wipe everything now** does, while the screen shows **Wrong password**. Nothing shows whether one is set. See [Panic button](#panic).":
    "**Senha de pânico**: com o bloqueio com senha ativado, **Definir a senha de pânico** em «Botão de pânico» define uma senha própria que, digitada na tela de bloqueio, apaga o Erevos como **Apagar tudo agora**, enquanto a tela mostra **Senha incorreta**. Nada mostra se há uma definida. Veja [Botão de pânico](#panic).",
  "**Calculator in place of Erevos**: on Android, under Launcher icons, a calculator that works can take the place of Erevos's icon; your code, then **=**, opens Erevos, which asks for its password as always. See [Appearance](#appearance).":
    "**Calculadora no lugar do Erevos**: no Android, em «Ícones do launcher», uma calculadora que funciona pode tomar o lugar do ícone do Erevos; o seu código, depois **=**, abre o Erevos, que pede a senha dele como sempre. Veja [Aparência](#appearance).",
  "**Chat with myself on your linked devices too**: notes, photos, files, voice messages and reminders written on one device go to the others, as do a reminder changed or seen and a note deleted. Those from before go once, both ways. See [Linked devices](#devices).":
    "**Conversa comigo também nos seus dispositivos conectados**: notas, fotos, arquivos, mensagens de voz e lembretes escritos em um dispositivo vão para os outros, assim como um lembrete mudado ou visto e uma nota apagada. Os de antes vão uma vez, nos dois sentidos. Veja [Dispositivos conectados](#devices).",
  "**Start when the phone turns on**: on Android, under In the background, Erevos can start by itself after the phone turns on, so the spaces set to say a message came while closed already say \"New message\", never which space or what. Off unless you choose it. See [Chat through a relay](#relay).":
    "**Iniciar quando o celular ligar**: no Android, em «Em segundo plano», o Erevos pode iniciar sozinho depois que o celular liga, de modo que os espaços configurados para avisar que chegou uma mensagem enquanto estão fechados já dizem “New message”, nunca qual espaço ou o quê. Desativado, a menos que você escolha. Veja [Conversar por um relay](#relay).",
  "**Moving the clock no longer ends the wait after wrong passwords**: it goes by the phone's own time since it started, which no one can set; after a restart it starts again from its beginning. See [Password lock](#lock).":
    "**Mexer no relógio não encerra mais a espera depois de senhas erradas**: ela segue o tempo próprio do celular desde que ele ligou, que ninguém pode ajustar; depois de um reinício ela recomeça do começo. Veja [Bloqueio com senha](#lock).",
  "**People you follow on Nostr, found where your other app keeps them**: with a key brought from another Nostr app, **Show the people you follow** also looks on the relays your key writes on, and says so when no relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**As pessoas que você segue no Nostr, encontradas onde o seu outro app as guarda**: com uma chave trazida de outro app Nostr, **Mostrar as pessoas que você segue** procura também nos relays onde a sua chave escreve, e avisa quando nenhum relay respondeu. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**Your Nostr name keeps the rest of your profile**: saving **Your name** changes only the name in your profile; a picture or words that another app of your key put there stay. Before, they could be wiped. See [Chats with other Nostr apps](#nostr-chats).":
    "**Seu nome no Nostr mantém o resto do seu perfil**: salvar **Seu nome** muda só o nome no seu perfil; uma foto ou palavras que outro app da sua chave pôs lá continuam. Antes, podiam ser apagadas. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**Screens come down when no keyboard is open, in every case**: the home screen's list and buttons, or a chat, could still stay up as if a keyboard were open after it had gone. Now Erevos asks Android itself whether a keyboard is shown, and with none they come down within a second.":
    "**As telas descem quando não há teclado aberto, em todos os casos**: a lista e os botões da tela inicial, ou uma conversa, ainda podiam ficar no alto como se houvesse um teclado aberto, depois que ele sumia. Agora o Erevos pergunta ao próprio Android se há um teclado na tela, e sem teclado elas descem em menos de um segundo.",
  // 4.0.0-rc.5
  "**New chat opens hidden chats sooner**: hold **New chat** down for a moment, not a whole second, and the field for a PIN of hidden chats opens; on Android the phone buzzes once as it opens. See [Hidden chats](#hidden).":
    "**Nova conversa abre mais depressa as conversas ocultas**: segure **Nova conversa** por um instante, não um segundo inteiro, e abre-se o campo para um PIN de conversas ocultas; no Android o telefone vibra uma vez ao abrir. Veja [Conversas ocultas](#hidden).",
  "**People you follow on Nostr**: under New chat in Nostr chats, **Show the people you follow** lists the people your Nostr key follows, with their names; tap one to write to them. See [Chats with other Nostr apps](#nostr-chats).":
    "**Pessoas que você segue no Nostr**: nas Conversas Nostr, em Nova conversa, **Mostrar as pessoas que você segue** lista as pessoas que a sua chave Nostr segue, com os nomes; toque numa para escrever para ela. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**Who makes Erevos, and its licence**: About Erevos now names its maker, and every file of Erevos's source code says whose it is and under which licence; the AGPL-3.0 licence has three added terms (keep the maker's name, mark a changed version, give it another name). See [What Erevos is](#about).":
    "**Quem faz o Erevos, e sua licença**: Sobre o Erevos agora diz quem o faz, e cada arquivo do código-fonte diz de quem é e sob qual licença; a licença AGPL-3.0 tem três condições adicionais (manter o nome do autor, marcar uma versão alterada como alterada e dar-lhe outro nome). Veja [O que é o Erevos](#about).",
  // 4.0.0-rc.4
  "**Numbers on the home chips**: each chip above the chats (All messages, SMS, Erevos, Matrix, XMPP, Nostr) shows how many messages are not read in it, as a small number after its name; muted chats and groups are not counted. See [Getting started](#start).":
    "**Números nos chips da tela inicial**: cada chip acima das conversas (Todos, SMS, Erevos, Matrix, XMPP, Nostr) mostra quantas mensagens não lidas há nele, com um número pequeno depois do nome; as conversas e os grupos em silêncio não contam. Veja [Primeiros passos](#start).",
  "**Open a photo full screen in Matrix, XMPP and Nostr chats**: tap a photo shown in a Matrix, XMPP or Nostr chat to see it on the whole screen, with zoom, turning with the phone and Save, as in a chat with a contact. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Foto em tela inteira nas conversas Matrix, XMPP e Nostr**: toque numa foto mostrada numa conversa Matrix, XMPP ou Nostr para vê-la na tela inteira, com zoom, rotação com o celular e Salvar, como na conversa com um contato. Veja [Matrix](#matrix), [XMPP](#xmpp) e [Conversas com outros apps Nostr](#nostr-chats).",
  "**Who got and who read your messages in groups**: in a group that is not public, your messages show ✓, then ✓✓ once they reached the phone of every member, and ✓✓✓ once every one read them. Hold one and choose **Who read it** to see who read it and when, whose phone it reached and when, and who has neither yet. A member whose Erevos is older says nothing. A linked computer shows the same marks. See [Chat through a relay](#relay) and [Group chats](#groups).":
    "**Quem recebeu e quem leu as suas mensagens nos grupos**: em um grupo que não é público, as suas mensagens mostram ✓, depois ✓✓ quando chegaram ao celular de cada membro, e ✓✓✓ quando todos as leram. Segure uma e escolha **Quem leu** para ver quem a leu e quando, em que celular ela chegou e quando, e quem ainda não fez nem uma coisa nem outra. Um membro com um Erevos mais antigo não avisa nada. Um computador conectado mostra as mesmas marcas. Veja [Conversar por um relay](#relay) e [Conversas em grupo](#groups).",
  "**Who read your messages in Matrix**: your messages in a Matrix chat show ✓ once the Matrix server took them and ✓✓✓ once every other member read them, as their Matrix apps tell their servers; **Who read it**, on a message held down, lists who read it and when, and who has not. Matrix has no mark for a message that reached a phone, so there is no ✓✓. See [Matrix](#matrix).":
    "**Quem leu as suas mensagens no Matrix**: as suas mensagens em uma conversa do Matrix mostram ✓ quando o servidor Matrix as recebeu e ✓✓✓ quando todos os outros membros as leram, como os apps Matrix deles avisam os servidores; **Quem leu**, numa mensagem segurada, lista quem a leu e quando, e quem não leu. O Matrix não tem marca para uma mensagem que chegou a um celular, então não existe ✓✓. Veja [Matrix](#matrix).",
  "**Quiet group messages for the marks**: the group message that says a message came or was read goes only to the senders concerned, and batched; after 300 such messages to some members only, the next goes to all, so no member falls behind in the phone's MLS keys (they accept a jump of 1000 at most). Groups let go of as their space closes send nothing more. See [Group chats](#groups).":
    "**Mensagens de grupo silenciosas para as marcas**: a mensagem de grupo que diz que uma mensagem chegou ou foi lida vai só aos remetentes envolvidos, e agrupada; depois de 300 dessas mensagens enviadas só a alguns membros, a seguinte vai a todos, para que nenhum membro fique para trás nas chaves MLS do celular (elas aceitam um salto de no máximo 1000). Os grupos soltos quando o espaço deles fecha não enviam mais nada. Veja [Conversas em grupo](#groups).",
  // 4.0.0-rc.3
  "**Bold, italic, code and hidden words**: in chats and groups, words typed between * become bold, between _ italic, between ~ struck through, between ` code, and between || hidden behind a grey bar until tapped. See [Chat through a relay](#relay).":
    "**Negrito, itálico, código e palavras escondidas**: em conversas e grupos, palavras entre * ficam em negrito, entre _ em itálico, entre ~ riscadas, entre ` como código, e entre || escondidas atrás de uma barra cinza até você tocar. Veja [Conversar por um relay](#relay).",
  "**Hidden photo**: under + in a chat or a group, a photo that shows blurred until it is tapped. See [Chat through a relay](#relay).":
    "**Foto escondida**: em + numa conversa ou num grupo, uma foto que aparece borrada até você tocar nela. Veja [Conversar por um relay](#relay).",
  "**Safety message**: under + in a chat, words to a contact that the relay sends by itself if you do not open Erevos for 6 hours to a week; each time you open it, they move on again. See [Chat through a relay](#relay).":
    "**Mensagem de segurança**: em + numa conversa, palavras para um contato que o relay envia sozinho se você não abrir o Erevos por um período de 6 horas a uma semana; cada vez que você o abre, elas são adiadas de novo. Veja [Conversar por um relay](#relay).",
  "**Name a member in a group with @**: type @ and pick a member; they are told of the message even if they muted the group. See [Group chats](#groups).":
    "**Cite um membro num grupo com @**: digite @ e escolha um membro; ele é avisado da mensagem mesmo que tenha silenciado o grupo. Veja [Conversas em grupo](#groups).",
  "**Reply, change, react and delete in XMPP chats**: hold a message in an XMPP chat or group to answer it, change your words, delete it for everyone or react with an emoji, as Conversations, Dino, Gajim, Monal and Kaidan do; and **typing…** shows while the other person writes. See [XMPP](#xmpp).":
    "**Responder, editar, reagir e apagar nas conversas XMPP**: segure uma mensagem em uma conversa ou grupo XMPP para respondê-la, mudar suas palavras, apagá-la para todos ou reagir com um emoji, como Conversations, Dino, Gajim, Monal e Kaidan fazem; e **digitando…** aparece enquanto a outra pessoa escreve. Veja [XMPP](#xmpp).",
  "**See who is writing in a Matrix chat**: **typing…** shows under a Matrix chat while someone writes in it, as the Matrix server says. It shows of you too only if you turn on **Say when I am writing** on the Matrix or XMPP screen: off at first, as it goes through the server not encrypted. See [Matrix](#matrix).":
    "**Veja quem está escrevendo num chat Matrix**: **digitando…** aparece embaixo de um chat Matrix enquanto alguém escreve nele, como o servidor Matrix diz. De você só aparece se você ativar **Avisar quando estou escrevendo** na tela do Matrix ou XMPP: desligado no início, pois passa pelo servidor sem criptografia. Veja [Matrix](#matrix).",
  "**Block someone on XMPP**: Block, at the bottom of an XMPP chat, keeps that person's messages, calls and requests from every app of your XMPP account; Unblock lets them through again. See [XMPP](#xmpp).":
    "**Bloqueie alguém no XMPP**: Bloquear, no fim de um chat XMPP, mantém as mensagens, chamadas e pedidos dessa pessoa longe de todos os apps da sua conta XMPP; Desbloquear a deixa passar de novo. Veja [XMPP](#xmpp).",
  "**Voice messages in XMPP chats**: hold the microphone under an XMPP chat's message box to record, and let go to send; it goes encrypted as the chat is, as Conversations sends one. See [XMPP](#xmpp).":
    "**Mensagens de voz nos chats XMPP**: segure o microfone abaixo da caixa de mensagem de um chat XMPP para gravar, e solte para enviar; vai criptografada como o chat, do jeito que o Conversations envia. Veja [XMPP](#xmpp).",
  "**Matrix groups from Erevos**: New group, on the Matrix screen, makes an encrypted group with a name and the people you invite; Join a group joins one by its address; Invite, in a group, asks someone else in; typing @ in a group names a member, who is told of it. See [Matrix](#matrix).":
    "**Grupos do Matrix pelo Erevos**: Novo grupo, na tela do Matrix, cria um grupo criptografado com um nome e as pessoas que você convidar; Entrar num grupo entra em um pelo endereço; Convidar, num grupo, chama outra pessoa; digitar @ num grupo cita um membro, que é avisado. Veja [Matrix](#matrix).",
  "**The panic button on a computer and on Sailfish OS**: Settings → Privacy and security → Panic button now wipes Erevos there too, with its automatic backups if you choose; on a computer it then starts again as new. See [Panic button](#panic).":
    "**O botão de pânico num computador e no Sailfish OS**: Configurações → Privacidade e segurança → Botão de pânico agora apaga o Erevos também lá, com os backups automáticos dele se você escolher; num computador ele depois começa como novo. Veja [Botão de pânico](#panic).",
  "**Every chat opens at its latest message**: chats with contacts, groups and SMS, and the Matrix, XMPP and Nostr chats, all open at the last message with the message bar under it, and have round arrows to the start, to where you left off (the first message that was new when you opened it) and to the end. See [Getting started](#start).":
    "**Cada conversa abre na sua última mensagem**: as conversas com contatos, os grupos e os SMS, e as conversas de Matrix, XMPP e Nostr abrem todas na última mensagem, com a barra de mensagem embaixo, e têm setas redondas para o início, para onde você parou (a primeira mensagem que era nova ao abrir) e para o fim. Veja [Primeiros passos](#start).",
  "**The panic button says when it refused**: when your panic app asked to wipe Erevos while the switch was off, or signed with another key, the panic screen now says so, with the time. An app that moves to a new key the way Android allows stays trusted; otherwise you can trust it again as it is now. See [Panic button](#panic).":
    "**O botão de pânico diz quando recusou**: quando seu app de pânico pediu para apagar o Erevos com o interruptor desligado, ou assinado com outra chave, a tela do botão de pânico agora avisa, com a hora. Um app que passa a uma chave nova do jeito que o Android permite continua de confiança; senão você pode confiar nele de novo como está agora. Veja [Botão de pânico](#panic).",
  "**The home screen's chips stay on one line**: with a Nostr, Matrix or XMPP chip as well, **Names** went to a line of its own and the chips moved. Now they stay on one line that slides to the side, and the chosen one is always in sight.":
    "**Os chips da tela inicial ficam em uma linha só**: com um chip de Nostr, Matrix ou XMPP a mais, **Nomes** ia para uma linha própria e os chips mudavam de lugar. Agora ficam em uma linha só que desliza para o lado, e o escolhido está sempre à vista.",
  "**Screens come down when the keyboard is gone**: back from another app that had its keyboard open, the home screen's buttons (or a chat's field) could stay up where the keyboard had been, until a keyboard opened again. Now they come down within a second.":
    "**As telas descem quando o teclado some**: ao voltar de outro app com o teclado aberto, os botões da tela inicial (ou o campo de uma conversa) podiam ficar no alto, onde estava o teclado, até um teclado abrir de novo. Agora descem em menos de um segundo.",
  // 4.0.0-rc.2
  "**See what you type in a password or a PIN**: every field for a password, a PIN or a token has an eye at its end: tap it to see what you type, and again to hide it. It is hidden again the next time. See [Password lock](#lock).":
    "**Veja o que você digita numa senha ou num PIN**: cada campo de senha, PIN ou token tem um olho no fim: toque nele para ver o que você digita, e de novo para esconder. Na próxima vez ele volta a ficar escondido. Veja [Bloqueio com senha](#lock).",
  "**A chat read as it opens stays read**: messages read while their chat was still opening, as Erevos ended a look at the relay, showed as unread on the home screen once you went back. Now they are marked read as soon as they show.":
    "**Uma conversa lida enquanto abre fica lida**: mensagens lidas enquanto a conversa ainda estava abrindo, enquanto o Erevos terminava de olhar no relay, apareciam como não lidas na tela inicial assim que você voltava. Agora elas ficam marcadas como lidas assim que aparecem.",
  "**Link for a website**: under New chat → Your contact link, a link to put on a web page, such as your contact page. It opens a page that offers Erevos to whoever has none yet, then adds you; what they send comes as a message request. See [Chat through a relay](#relay).":
    "**Link para um site**: em Nova conversa → Seu link de contato, um link para pôr numa página web, como sua página de contato. Abre uma página que oferece o Erevos a quem ainda não o tem e depois adiciona você; o que enviar chega como solicitação de mensagem. Veja [Conversar por um relay](#relay).",
  "**An update's download that stalls is tried again**: when the connection brings nothing for a while, Erevos starts the download again by itself, three times in all, and then says so in its own words. See [Updates](#updates).":
    "**Um download de atualização que trava é tentado de novo**: quando a conexão não traz nada durante algum tempo, o Erevos recomeça o download sozinho, três vezes ao todo, e depois avisa com palavras próprias. Veja [Atualizações](#updates).",
  // 4.0.0-rc.1
  "**Pieces of photos through Nostr stay with their chats**: while a photo that comes through Nostr waits for the rest of its pieces, they are now kept encrypted with the space or the hidden chats they came for, no longer apart where they could be counted, so nothing outside a hidden chats' password says that a photo is on its way to them. Pieces kept before go to the first chats whose photo they are, or after four days. See [Through Nostr](#nostr).":
    "**Os pedaços de fotos pelo Nostr ficam com as suas conversas**: enquanto uma foto que chega pelo Nostr espera o resto dos seus pedaços, eles agora são guardados criptografados com o espaço ou as conversas ocultas para os quais vieram, não mais à parte, onde podiam ser contados, então nada fora da senha de conversas ocultas diz que uma foto está a caminho delas. Os pedaços guardados antes vão para as primeiras conversas de cuja foto são, ou saem após quatro dias. Veja [Pelo Nostr](#nostr).",
  "**Encrypted SMS when nothing else works, if you choose**: on Android, when the relay, Nostr, the phones nearby and LoRa all fail, a text to an Erevos contact whose number is linked can go by SMS, end-to-end encrypted, hidden from their SMS app. Off until you turn it on, for all such contacts under Settings → Phone and SMS → SMS, or for one in a chat's Details. It costs SMS (3 for a short text, up to 10 for a longer one), and the phone company sees who wrote to whom, and when. Both phones need Erevos as the SMS app. See [SMS](#sms).":
    "**SMS criptografados quando nada mais funciona, se você quiser**: no Android, quando o relay, o Nostr, os celulares por perto e o LoRa falham todos, um texto para um contato do Erevos com número vinculado pode ir por SMS, criptografado de ponta a ponta e escondido do app de SMS dele. Desativado até você ativar, para todos esses contatos em Configurações → Telefone e SMS → SMS, ou para um nos Detalhes de uma conversa. Custa SMS (3 para um texto curto, até 10 para um mais longo), e a operadora vê quem escreveu para quem, e quando. Os dois celulares precisam do Erevos como app de SMS. Veja [SMS](#sms).",
  "**Answer a hidden call with Answer**: on the \"Incoming call\" screen with no name that a call to your hidden chats brings, **Answer** now asks for the PIN, as the small sign does, and the right PIN answers the call; before, it could not connect, and only the small sign could. See [Hidden chats](#hidden).":
    "**Atender uma chamada oculta com Atender**: na tela “Chamada recebida” sem nome que uma chamada para as suas conversas ocultas traz, **Atender** agora pede o PIN, como o pequeno sinal, e o PIN certo atende a chamada; antes, não conseguia conectar, e só o pequeno sinal conseguia. Veja [Conversas ocultas](#hidden).",
  "**Spam SMS come quietly**: on Android, an SMS that the spam filter's own words catch, a link with words that try to fool from a number that is no contact and that you never answered, still goes to Spam but no longer shows a notice or makes a sound. Spam by your own words and rules still shows one, as they stay encrypted in the space; with the Spam filter off, every SMS does. See [SMS](#sms).":
    "**SMS de spam chegam em silêncio**: no Android, um SMS que as palavras do próprio filtro de spam pegam, um link com palavras que tentam enganar de um número que não é contato e a que você nunca respondeu, ainda vai para o Spam, mas não mostra mais aviso nem faz som. O spam pelas suas próprias palavras e regras ainda mostra um, pois elas ficam criptografadas no espaço; com o Filtro de spam desligado, todo SMS mostra. Veja [SMS](#sms).",
  '**What\'s new in two parts**: each version says first what changes for you, then what changed under the hood: fixes, speed, battery and security inside. See [Updates](#updates).':
    '**Novidades em duas partes**: cada versão diz primeiro o que muda para você e depois o que mudou nos bastidores: correções, velocidade, bateria e segurança por dentro. Veja [Atualizações](#updates).',
  '**A contact\'s SMS no longer stay counted as new**: opening their chat reads all of them, the earlier ones too, not only those that show.':
    '**Os SMS de um contato não ficam mais contados como novos**: abrir a conversa lê todos, também os anteriores, não só os que aparecem.',
  '**A message no longer waits when Tor cannot reach the relay**: with Tor for messages, it goes straight at once, as the Tor settings say. See [Through Tor](#tor).':
    '**Uma mensagem não fica mais esperando quando o Tor não chega ao relay**: com o Tor para as mensagens, ela sai direto na hora, como dizem as configurações do Tor. Veja [Pelo Tor](#tor).',
  '**Background notices no longer stop after a network change**: when the connection of a wait at the relay died on the way (Wi-Fi to mobile data, the relay restarting), Erevos took the relay for one from before, which cannot wait, for the whole run: contacts\' messages then came up to ten minutes late, and hidden chats, closed spaces and hidden rings said nothing until Erevos was restarted. See [Chat through a relay](#relay).':
    '**Os avisos em segundo plano não param mais depois de uma troca de rede**: quando a conexão de uma espera no relay morria no caminho (de Wi-Fi para dados móveis, reinício do relay), o Erevos tomava o relay por um antigo, que não sabe esperar, durante toda a execução: as mensagens dos contatos chegavam até dez minutos atrasadas, e as conversas ocultas, os espaços fechados e os toques ocultos não diziam nada até reiniciar o Erevos. Veja [Conversar por um relay](#relay).',
  '**A call hung up at once no longer rings**: when the hang-up came in the same look as the call, the phone rang 45 seconds for a call nobody was on; the same for a group call its starter left at once. See [Chat through a relay](#relay).':
    '**Uma chamada desligada na hora não toca mais**: quando o desligamento chegava no mesmo olhar que a chamada, o telefone tocava 45 segundos por uma chamada em que não havia ninguém; o mesmo para uma chamada de grupo que quem a começou deixou na hora. Veja [Conversar por um relay](#relay).',
  '**A hidden call rings once**: a place with Receive while closed and a ring queue rang twice for one call, and a call taken while hidden chats were open rang again as they closed. See [Hidden chats](#hidden).':
    '**Uma chamada oculta toca uma vez**: um lugar com Receber quando fechadas e uma fila de toque tocava duas vezes por uma chamada, e uma chamada atendida com as conversas ocultas abertas voltava a tocar quando elas fechavam. Veja [Conversas ocultas](#hidden).',
  '**A member\'s contact link no longer says New message**: the answer to an ask from a group only adds the contact, with no notice. See [Group chats](#groups).':
    '**O link de contato de um membro não diz mais Nova mensagem**: a resposta a um pedido feito de um grupo só adiciona o contato, sem aviso. Veja [Conversas em grupo](#groups).',
  '**The birthday notice and the phone\'s incoming call no longer replace each other**: they had the same notice number. See [Contacts](#contacts).':
    '**O aviso de aniversário e a chamada recebida do telefone não se substituem mais**: tinham o mesmo número de aviso. Veja [Contatos](#contacts).',
  '**A closed space tells of its contacts\' messages too**: since each contact writes to a queue of their own, a space that says a message came while another is open told only of group messages and first messages from new contacts. It now asks about its contacts\' queues too, up to 64. See [Chat through a relay](#relay).':
    '**Um espaço fechado avisa também das mensagens dos contatos dele**: como cada contato escreve numa fila própria, um espaço que avisa que chegou mensagem enquanto outro está aberto só avisava de mensagens de grupos e de primeiras mensagens de contatos novos. Agora ele pergunta também pelas filas dos contatos dele, até 64. Veja [Conversar por um relay](#relay).',
  '**The user guide is in every language of the app**: it shows in the one you chose, and names the buttons as the app shows them. See [Language](#start).':
    '**O guia de uso está em todos os idiomas do app**: aparece no que você escolheu e chama os botões como o app os mostra. Veja [Idioma](#start).',
  '**Location finds where you are, indoors too**: the phone looks by satellite and by its network at once, a sheet says it is looking, and when nothing is found it says why, with Try again. See [Chat through a relay](#relay).':
    '**Localização encontra onde você está, também em lugares fechados**: o celular procura por satélite e pela rede dele ao mesmo tempo, uma folha diz que está procurando, e quando nada é encontrado diz por quê, com Tentar de novo. Veja [Conversar por um relay](#relay).',
  '**The web app\'s icon counts what is not read**: on an iPhone, with notifications on for the space, Erevos\'s icon on the home screen shows how many messages are not read, never a hidden chat\'s, unless turned off under Settings → Notifications → Number on the icon. See [On an iPhone](#iphone).':
    '**O ícone do app web conta o que não foi lido**: num iPhone, com as notificações ativas para o espaço, o ícone do Erevos na tela de início mostra quantas mensagens não foram lidas, nunca as de uma conversa oculta, a não ser que você o desligue em Configurações → Notificações → Número no ícone. Veja [Num iPhone](#iphone).',
  "**Notifications for each chat**: on Android, mute a chat or a group for 8 hours, a week or always, and give its messages and its calls a sound of their own, or none. See [Chat through a relay](#relay).":
    "**Notificações para cada conversa**: no Android, silencie uma conversa ou um grupo por 8 horas, uma semana ou sempre, e dê às mensagens e chamadas dela um som próprio, ou nenhum. Veja [Conversar por um relay](#relay).",
  "**A chat locked with its own PIN stays locked**: when its contact's Erevos started a new conversation, as it does about once a month, the chat lost its PIN, and a public group joined again lost its own. See [Hidden chats](#hidden).":
    "**Uma conversa bloqueada com um PIN próprio continua bloqueada**: quando o Erevos do contato começava uma conversa nova, como faz mais ou menos uma vez por mês, a conversa perdia o PIN, e um grupo público em que você entrou de novo perdia o seu. Veja [Conversas ocultas](#hidden).",
  "**Erevos's icon keeps the number of messages not read, on Android**: leaving Erevos with messages not read, a notice without sound keeps how many until you read them, and the launcher shows it on the icon, as a number or a dot. Settings → Notifications → Number on the icon turns it off. See [Chat through a relay](#relay).":
    "**O ícone do Erevos guarda o número de mensagens não lidas, no Android**: ao sair do Erevos com mensagens não lidas, uma notificação sem som guarda quantas são até você lê-las, e o launcher a mostra no ícone, como número ou ponto. Configurações → Notificações → Número no ícone o desliga. Veja [Conversar por um relay](#relay).",
  "**The web app's notifications, more dependable**: no New message over Erevos while it is open, and a push held back while the phone was offline no longer counts messages you already read (both with your relay updated), every notice sounds in Chrome, Firefox and Edge, they come back by themselves when the browser changes its push address, and Notifications while closed says when the browser blocks them or your relay was not told yet that they are off. See [On an iPhone](#iphone).":
    "**As notificações do app web, mais confiáveis**: nenhuma Nova mensagem por cima do Erevos enquanto ele está aberto, e um push retido enquanto o celular estava sem conexão não conta mais as mensagens que você já leu (as duas coisas com o seu relay atualizado), cada aviso faz som no Chrome, no Firefox e no Edge, elas voltam sozinhas quando o navegador muda o endereço de push dele, e Notificações com o app fechado diz quando o navegador as bloqueia ou quando o seu relay ainda não foi avisado de que elas estão desativadas. Veja [Num iPhone](#iphone).",
  "**Calls ring in the web app, on the computer and on Sailfish OS**: a call that comes while Erevos is open now rings, where only its screen showed, and vibrates where the phone can. On an iPhone it rings once you have touched Erevos, and not on silent. See [On an iPhone](#iphone).":
    "**As chamadas tocam no app web, no computador e no Sailfish OS**: uma chamada que chega enquanto o Erevos está aberto agora toca, onde antes só aparecia a tela dela, e vibra onde o telefone pode. Num iPhone ela toca depois que você tocou no Erevos, e não no silencioso. Veja [Num iPhone](#iphone).",
  '**Erevos on a computer keeps running with its window closed**: in the system tray (on a Mac, in the Dock) it goes on receiving, a call rings and brings the window back, and a notification says how many messages are not read, never who or what. Turn it off under Settings → Notifications → In the background. See [On a computer](#desktop).':
    '**O Erevos no computador continua rodando com a janela fechada**: na bandeja do sistema (num Mac, no Dock) ele continua recebendo, uma chamada toca e traz a janela de volta, e uma notificação diz quantas mensagens não foram lidas, nunca de quem nem o quê. Desligue em Configurações → Notificações → Em segundo plano. Veja [Num computador](#desktop).',
  "**Erevos on Sailfish OS tells of messages and calls while it is closed**: while it is out of sight or closed, a small helper waits at the relay for the open space, a notification says how many messages came, never who or what, and a call rings with the phone's ringtone. See [On Sailfish OS](#sailfish).":
    "**O Erevos no Sailfish OS avisa de mensagens e chamadas enquanto está fechado**: enquanto não está à vista ou está fechado, um pequeno ajudante espera no relay pelo espaço aberto, uma notificação diz quantas mensagens chegaram, nunca de quem nem o quê, e uma chamada toca com o toque do celular. Veja [No Sailfish OS](#sailfish).",
  "**The relay's pushes to the web app, sturdier**: a push the push service could not take just then is sent again, a call goes before the messages waiting their turn, and whoever runs the relay can allow another push service. Your relay needs an update for it.":
    "**Os pushes do relay para o app web, mais robustos**: um push que o serviço de push não pôde aceitar naquele momento é enviado de novo, uma chamada passa na frente das mensagens que esperam a vez delas, e quem cuida do relay pode permitir outro serviço de push. O seu relay precisa de uma atualização para isso.",
  "**Permissions checks every notice Erevos uses**: on Android, the message notice without sound or with a chat's own sound, and the reminders', turned off, now show there, with a button to each. See [Chat through a relay](#relay).":
    "**Permissões verifica cada aviso que o Erevos usa**: no Android, o aviso de mensagens sem som ou com o som próprio de uma conversa, e o dos lembretes, quando desativados, agora aparecem ali, com um botão para cada um. Veja [Conversar por um relay](#relay).",
  '**Hidden chats say what their switches need**: Say when a message comes and Ring calls when closed say so when Settings → Notifications → In the background lets them do nothing. See [Hidden chats](#hidden).':
    '**As conversas ocultas dizem do que os interruptores delas precisam**: Avisar quando chega uma mensagem e Tocar as chamadas quando fechadas avisam quando Configurações → Notificações → Em segundo plano não as deixa fazer nada. Veja [Conversas ocultas](#hidden).',
  "**Truer words about notices**: Settings and the guide give the notices' own words and say what each one needs. See [Chat through a relay](#relay).":
    "**Palavras mais fiéis sobre os avisos**: as Configurações e o guia dão as próprias palavras dos avisos e dizem do que cada um precisa. Veja [Conversar por um relay](#relay).",
  "**Calls ring as they should**: with Do Not Disturb only when their notice may break through, with a phone's clock off too once the relay is updated, and to the end on Android 7 and 8; a second call is told busy, and a ring stops only for its own call. See [Chat through a relay](#relay).":
    "**As chamadas tocam como devem**: com o Não perturbe só quando o aviso delas pode passar por ele, também com o relógio de um celular errado assim que o relay for atualizado, e até o fim no Android 7 e 8; uma segunda chamada recebe sinal de ocupado, e um toque só para por causa da própria chamada. Veja [Conversar por um relay](#relay).",
  '**Hidden calls**: one turned down no longer leaves Erevos over the lock screen, one that comes while the password screen shows comes over it, and none rings twice. See [Hidden chats](#hidden).':
    '**Chamadas ocultas**: uma recusada não deixa mais o Erevos sobre a tela de bloqueio, uma que chega enquanto a tela da senha aparece vem por cima dela, e nenhuma toca duas vezes. Veja [Conversas ocultas](#hidden).',
  '**Notices come again at once after a change of network**, and receiving starts again as Erevos shows when Android refused it. See [Chat through a relay](#relay).':
    '**Os avisos voltam a chegar na hora depois de uma mudança de rede**, e o recebimento começa de novo quando o Erevos aparece na tela, se o Android o tinha recusado. Veja [Conversar por um relay](#relay).',
  "**Hidden chats' notices tell each message once**: what came since a place last looked is told as it closes, a call that rang is not told again as a message, and a place whose queue the relay lost keeps its switch on. See [Hidden chats](#hidden).":
    "**Os avisos das conversas ocultas falam de cada mensagem uma vez**: o que chegou desde a última vez que uma posição olhou é avisado quando ela fecha, uma chamada que tocou não é avisada de novo como mensagem, e uma posição cuja fila o relay perdeu mantém o interruptor dela ativado. Veja [Conversas ocultas](#hidden).",
  '**Hidden chats close while Erevos is away**, after 30 seconds, so a call to them meanwhile rings with their PIN to answer. See [Hidden chats](#hidden).':
    '**As conversas ocultas fecham enquanto o Erevos está fora da tela**, depois de 30 segundos, então uma chamada para elas nesse meio-tempo toca com o PIN delas para atender. Veja [Conversas ocultas](#hidden).',
  '**A voice message counts once**, on its last part, also when it goes again whole.':
    '**Uma mensagem de voz conta uma vez**, na última parte dela, também quando ela vai de novo inteira.',
  '**The number on the icon counts only what is still there**: a message deleted for everyone, or read on a linked computer, no longer counts. See [Chat through a relay](#relay).':
    '**O número no ícone conta só o que ainda está lá**: uma mensagem apagada para todos, ou lida num computador conectado, deixa de contar. Veja [Conversar por um relay](#relay).',
  '**Messages sent for later** tell of themselves only while their space is open, without sound if sent so.':
    '**As mensagens agendadas** só avisam de si enquanto o espaço delas está aberto, sem som se foram enviadas assim.',
  '**SMS**: one to the chat on screen only sounds there, they are marked read only while their screen shows, and Android names their notices SMS. See [SMS](#sms).':
    '**SMS**: um para a conversa na tela só toca ali, eles só são marcados como lidos enquanto a tela deles aparece, e o Android chama os avisos deles de SMS. Veja [SMS](#sms).',
  "**Reminders**: one seen in Chat with myself goes from the notice, a hidden place's go with a new PIN, and birthdays come at 9:00. See [Getting started](#start).":
    "**Lembretes**: um visto na Conversa comigo sai do aviso, os de uma posição oculta saem com um PIN novo, e os aniversários chegam às 9:00. Veja [Primeiros passos](#start).",
  '**Nostr reads as soon as Tor is ready.** See [Through Nostr](#nostr).':
    '**O Nostr lê assim que o Tor está pronto.** Veja [Pelo Nostr](#nostr).',
  "**Erevos's notices show its mark** in the status bar.":
    "**Os avisos do Erevos mostram a marca dele** na barra de status.",
  '**Notices are asked for with receiving off too**, when Say a message came is on.':
    '**Os avisos são pedidos também com o recebimento desativado**, quando Avisar quando chega mensagem está ativado.',
  "**Photos open on the whole screen**: tap one to see it edge to edge, zoom in with two fingers or a double tap, and tap again to hide or show what is around it; big photos open as small ones do. Erevos also turns with the phone while the phone's Auto-rotate is on, and a photo shown on its own even when it is off. See [Chat through a relay](#relay).":
    '**As fotos abrem na tela inteira**: toque numa para vê-la de ponta a ponta, amplie com dois dedos ou um toque duplo, e toque de novo para esconder ou mostrar o que há em volta; fotos grandes abrem como as pequenas. O Erevos também gira com o telefone enquanto Girar automaticamente estiver ativado nele, e uma foto vista sozinha mesmo quando está desativado. Veja [Conversar por um relay](#relay).',
  "**Matrix accounts in Erevos**: sign a space in to Matrix and chat with people who use Element or another Matrix app, end-to-end encrypted, under Settings → Relay and networks → Matrix. These chats are not anonymous, and say so: the Matrix server sees who talks with whom. Text, photos and files. See [Matrix](#matrix).":
    "**Contas Matrix no Erevos**: entre no Matrix com um espaço e converse com pessoas que usam o Element ou outro app Matrix, com criptografia de ponta a ponta, em Configurações → Relay e redes → Matrix. Essas conversas não são anônimas, e avisam: o servidor Matrix vê quem fala com quem. Texto, fotos e arquivos. Veja [Matrix](#matrix).",
  "**Every network's chats on the home screen**: once you sign in to Matrix, its chats are in the list with the Erevos chats and the SMS, newest first, each marked Matrix, and the Matrix chip shows them alone, as SMS and Erevos do. See [Matrix](#matrix).":
    "**As conversas de todas as redes na tela inicial**: depois que você entra no Matrix, as conversas dele ficam na lista com as conversas do Erevos e os SMS, as mais recentes primeiro, cada uma marcada Matrix, e o chip Matrix mostra só elas, como SMS e Erevos. Veja [Matrix](#matrix).",
  '**Test versions before a release**: Erevos reads a version such as 4.0.0-rc.1, a test version that comes before 4.0.0, when it looks for updates, tells of a new version and shows what is new. See [Updates](#updates).':
    '**Versões de teste antes de uma versão**: o Erevos lê uma versão como 4.0.0-rc.1, uma versão de teste que vem antes da 4.0.0, ao procurar atualizações, ao avisar de uma nova versão e ao mostrar as novidades. Veja [Atualizações](#updates).',
  "**Check Matrix devices by emoji**: in a chat with one person on Matrix, Check by emoji shows you both seven pictures; if they match, nobody sits in between, and Element sees the check too. Check this device with another of yours makes your own Element trust Erevos. See [Matrix](#matrix).":
    "**Verificar dispositivos do Matrix por emoji**: numa conversa com uma pessoa no Matrix, Verificar por emoji mostra aos dois sete imagens; se forem iguais, ninguém está no meio, e o Element também vê a verificação. Verificar este dispositivo com outro seu faz o seu próprio Element confiar no Erevos. Veja [Matrix](#matrix).",
  "**Automatic backups to your own server too**: on Android, each automatic backup can also go to a folder on a server you choose, such as your Nextcloud, over WebDAV. Off until you add one. The server gets random bytes under a random name and cannot open them; it still sees your account, your address and when. See [Backups](#backup).":
    "**Backups automáticos também para o seu próprio servidor**: no Android, cada backup automático também pode ir para uma pasta num servidor que você escolher, como o seu Nextcloud, por WebDAV. Desligado até você adicionar um. O servidor recebe bytes aleatórios com um nome aleatório e não consegue abri-los; ainda assim vê sua conta, seu endereço e quando. Veja [Backups](#backup).",
  "**Matrix Security Key and key backup**: enter the Security Key Element made, under Settings → Relay and networks → Matrix, and earlier messages open, new keys are backed up, and your other devices trust Erevos. An account with none can set one up there. See [Matrix](#matrix).":
    "**Chave de segurança e backup de chaves do Matrix**: digite a chave de segurança que o Element criou, em Configurações → Relay e redes → Matrix, e as mensagens anteriores abrem, as chaves novas ganham backup, e seus outros dispositivos confiam no Erevos. Uma conta sem ela pode criar uma ali. Veja [Matrix](#matrix).",
  "**Matrix through Tor**: on Android, a space's Matrix account follows its choice under Settings → Relay and networks → Tor, so the Matrix server no longer sees where you are; the Matrix screen says when it goes through Tor. See [Matrix](#matrix).":
    "**Matrix pelo Tor**: no Android, a conta Matrix de um espaço segue a escolha dele em Configurações → Relay e redes → Tor, então o servidor Matrix não vê mais onde você está; a tela do Matrix diz quando vai pelo Tor. Veja [Matrix](#matrix).",
  "**XMPP accounts in Erevos**: sign a space in to XMPP, under Settings → Relay and networks → XMPP, and chat with people who use Conversations, Monal, Gajim, Dino or another XMPP app, encrypted with OMEMO. These chats are not anonymous, and say so: the XMPP server sees who talks with whom. Text with delivery and read marks, photos and files, in the home list under an XMPP chip of its own, and through Tor on Android as you chose. See [XMPP](#xmpp).":
    "**Contas XMPP no Erevos**: faça um espaço entrar no XMPP, em Configurações → Relay e redes → XMPP, e converse com pessoas que usam o Conversations, o Monal, o Gajim, o Dino ou outro app XMPP, criptografado com OMEMO. Essas conversas não são anônimas, e dizem isso: o servidor XMPP vê quem fala com quem. Texto com marcas de entrega e de leitura, fotos e arquivos, na lista da tela inicial sob um chip XMPP próprio, e pelo Tor no Android como você escolheu. Veja [XMPP](#xmpp).",
  "**Voice and video calls with people on XMPP**: the two tiles at the top of an XMPP chat call the person, and their calls ring on the same screen as Erevos's own, with apps that call as Conversations does. The call goes through your call relay or the XMPP server's, so they do not learn your address; the key that proves it passes through the XMPP servers, which could put themselves in between. See [XMPP](#xmpp).":
    "**Chamadas de voz e vídeo com pessoas no XMPP**: os dois blocos no topo de uma conversa XMPP ligam para a pessoa, e as chamadas dela tocam na mesma tela que as do Erevos, com apps que ligam como o Conversations. A chamada passa pelo seu relay de chamadas ou pelo do servidor XMPP, então ela não fica sabendo seu endereço; a chave que a comprova passa pelos servidores XMPP, que poderiam se colocar no meio. Veja [XMPP](#xmpp).",
  "**Voice and video calls with people on Matrix**: on Android, the two tiles at the top of a Matrix chat call with Element Call, the call app of Element and Element X, which opens inside Erevos in a window of its own, and their calls ring here as Erevos's own do. Sound and picture are end-to-end encrypted and go through the media server your Matrix server names, never through Tor. See [Matrix](#matrix).":
    "**Chamadas de voz e vídeo com pessoas no Matrix**: no Android, os dois blocos no topo de uma conversa Matrix ligam com o Element Call, o app de chamadas do Element e do Element X, que abre dentro do Erevos numa janela própria, e as chamadas delas tocam aqui como as do Erevos. Som e imagem são criptografados de ponta a ponta e passam pelo servidor de mídia que o seu servidor Matrix indica, nunca pelo Tor. Veja [Matrix](#matrix).",
  "**Voice and video calls with people on Matrix, in the web app and on a computer**: the two tiles at the top of a Matrix chat call with Element Call there too, as on Android, over the app; its back arrow makes it small in a corner, so you can keep using Erevos during the call. Element Call runs apart from Erevos and can read nothing of it. See [Matrix](#matrix).":
    "**Chamadas de voz e vídeo com pessoas no Matrix, no app web e no computador**: os dois blocos no topo de uma conversa Matrix ligam com o Element Call também lá, como no Android, por cima do app; a seta de voltar da janela a deixa pequena num canto, para você continuar usando o Erevos durante a chamada. O Element Call roda separado do Erevos e não consegue ler nada dele. Veja [Matrix](#matrix).",
  "**Chats with people on other Nostr apps**: give a space a Nostr key of its own, under Settings → Relay and networks → Nostr chats, and chat with people who use Damus, Amethyst, Primal, 0xchat or another Nostr app, one to one or in groups, encrypted as NIP-17 asks: the relays see whom a message is for, not who wrote it. These chats are not anonymous, and say so: your key is the same to everyone you write to. Text, photos, files and reactions, in the home list under a Nostr chip of its own, and through Tor on Android as you chose. See [Chats with other Nostr apps](#nostr-chats).":
    "**Conversas com pessoas em outros apps Nostr**: dê a um espaço uma chave Nostr própria, em Configurações → Relay e redes → Conversas Nostr, e converse com pessoas que usam Damus, Amethyst, Primal, 0xchat ou outro app Nostr, a dois ou em grupo, criptografado como o NIP-17 pede: os relays veem para quem é uma mensagem, não quem a escreveu. Estas conversas não são anônimas, e dizem isso: sua chave é a mesma para todos com quem você fala. Texto, fotos, arquivos e reações, na lista da tela inicial sob um botão Nostr próprio, e pelo Tor no Android como você escolheu. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**Notices for Matrix, XMPP and Nostr messages**: a message in a chat on Matrix, XMPP or Nostr shows a notice and counts in the number on Erevos's icon, as in Erevos's own chats. On Android, Notifications at the bottom of such a chat mutes it or gives it a sound of its own, and an XMPP or Matrix call rings with its chat's ringtone. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Avisos das mensagens de Matrix, XMPP e Nostr**: uma mensagem numa conversa de Matrix, XMPP ou Nostr mostra um aviso e conta no número do ícone do Erevos, como nas conversas do próprio Erevos. No Android, Notificações, no fim de uma conversa assim, silencia ela ou dá a ela um som próprio, e uma chamada XMPP ou Matrix toca com o toque da conversa dela. Veja [Matrix](#matrix), [XMPP](#xmpp) e [Conversas com outros apps Nostr](#nostr-chats).",
  "**A closed space tells of Matrix messages**: on Android, Say a message came under While this space is closed, on the Matrix screen, has a closed space say \"New message\" when something comes on Matrix while another space is open, never what, from whom or in which chat. Off until you choose it. The Matrix server then tells the space's relay of each message, with no words in it: it learns the relay's address, and the relay when messages come. See [Matrix](#matrix).":
    "**Um espaço fechado avisa das mensagens do Matrix**: no Android, «Avisar quando chega mensagem» em «Enquanto este espaço está fechado», no ecrã do Matrix, faz um espaço fechado dizer «Nova mensagem» quando chega algo no Matrix enquanto outro espaço está aberto, nunca o quê, de quem ou em que conversa. Desligado até o escolheres. O servidor Matrix avisa então o relay do espaço de cada mensagem, sem nenhuma palavra dela: fica a saber o endereço do relay, e o relay quando chegam mensagens. Ver [Matrix](#matrix).",
  "**Made with others' open source**: About Erevos, and the guide, now name the open-source projects Erevos is built on, with their makers and their licences. See [What Erevos is](#about).":
    "**Feito com o código aberto de outros**: Em Sobre o Erevos e no guia aparecem agora os projetos de código aberto em que o Erevos se apoia, com seus autores e suas licenças. Veja [O que é o Erevos](#about).",
  "**Groups on XMPP**: under Settings → Relay and networks → XMPP, make a private group with your contacts, encrypted with OMEMO for every member as Conversations' private groups are, or join a group by its address, and answer invitations to groups. A group that is not private, a channel, is not encrypted, and says so. Your groups follow your account's other XMPP apps, and a channel tells only of messages that name you. See [XMPP](#xmpp).":
    "**Grupos no XMPP**: em Configurações → Relay e redes → XMPP, crie um grupo privado com seus contatos, criptografado com OMEMO para cada membro como os grupos privados do Conversations, ou entre num grupo pelo endereço, e responda aos convites para grupos. Um grupo que não é privado, um canal, não é criptografado, e diz isso. Seus grupos acompanham os outros apps XMPP da sua conta, e um canal avisa só das mensagens que citam você. Veja [XMPP](#xmpp).",
  "**More in Matrix chats**: hold a message to react to it, reply to it, copy it and, if it is yours, edit it or delete it for everyone. Load earlier messages brings in older ones, and the microphone under the message box sends voice messages that Element plays too. Reactions are not encrypted, as Element sends them. See [Matrix](#matrix).":
    "**Mais nas conversas do Matrix**: segure uma mensagem para reagir a ela, respondê-la, copiá-la e, se for sua, editá-la ou apagá-la para todos. «Carregar mensagens anteriores» traz as mais antigas, e o microfone abaixo do campo de mensagem envia mensagens de voz que o Element também toca. As reações não são criptografadas, como o Element as envia. Veja [Matrix](#matrix).",
  "**Video added to an XMPP call**: in a voice call with someone on XMPP, either of you can turn on video with Add video; the other is asked first and can say Not now. It works with apps that add video to a call as Conversations does. See [XMPP](#xmpp).":
    "**Vídeo adicionado a uma chamada do XMPP**: numa chamada de voz com alguém no XMPP, qualquer um dos dois pode ligar o vídeo com «Adicionar vídeo»; a outra pessoa é perguntada primeiro e pode dizer «Agora não». Funciona com apps que adicionam vídeo a uma chamada como o Conversations. Veja [XMPP](#xmpp).",
  "**Voice messages and replies in Nostr chats**: hold the microphone under the message box to send a voice message, which plays with Play; hold a message to reply to it, and the answer shows the message it is to, here and in other Nostr apps. See [Chats with other Nostr apps](#nostr-chats).":
    "**Mensagens de voz e respostas nas conversas do Nostr**: segure o microfone abaixo do campo de mensagem para enviar uma mensagem de voz, que toca com «Reproduzir»; segure uma mensagem para respondê-la, e a resposta mostra a mensagem a que responde, aqui e em outros apps Nostr. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**OMEMO 2 in XMPP chats**: a message to someone whose app speaks OMEMO 2, as Kaidan does, now goes with OMEMO 2 to that app and with OMEMO 0.3 to their others, as before. The XMPP screen shows this device's key both ways, to compare with what each app shows. See [XMPP](#xmpp).":
    "**OMEMO 2 nas conversas do XMPP**: uma mensagem para alguém cujo app fala OMEMO 2, como o Kaidan, agora vai com OMEMO 2 para esse app e com OMEMO 0.3 para os outros apps dele, como antes. A tela do XMPP mostra a chave deste dispositivo das duas maneiras, para comparar com o que cada app mostra. Veja [XMPP](#xmpp).",
  "**Hidden chats can have their own Matrix, XMPP and Nostr accounts**: under the list of a place of hidden chats, Matrix, XMPP and Nostr open an account of that place alone, apart from the space's, kept encrypted with the hidden chats' key. Its chats show among the hidden chats only. It connects while they are open, and while they are closed too if Receive while closed is on, as the hidden chats do: then a message says only \"New message\", and a call rings with no name and is answered with the PIN. See [Hidden chats](#hidden).":
    "**As conversas ocultas podem ter as próprias contas Matrix, XMPP e Nostr**: abaixo da lista de uma posição de conversas ocultas, Matrix, XMPP e Nostr abrem uma conta só daquela posição, separada da do espaço e guardada criptografada com a chave das conversas ocultas. As conversas dela aparecem só entre as conversas ocultas. Ela se conecta enquanto estão abertas, e também enquanto estão fechadas se Receber quando fechadas estiver ligado, como as próprias conversas ocultas: então uma mensagem diz só “Nova mensagem”, e uma chamada toca sem nome e é atendida com o PIN. Veja [Conversas ocultas](#hidden).",
  "**Matrix, XMPP and Nostr in backups**: a backup now holds the Matrix, XMPP and Nostr accounts of every space and of its hidden chats. After a restore, a Nostr key comes back with its chats as they were; an XMPP account goes on as a new device of the account, with its contacts and chats; a Matrix account is let go of on this phone, and the space signs in again as a new device; its Security Key opens the messages from before. See [Backups](#backup).":
    "**Matrix, XMPP e Nostr nos backups**: um backup agora guarda as contas Matrix, XMPP e Nostr de cada espaço e de suas conversas ocultas. Depois de restaurar, uma chave Nostr volta com suas conversas como estavam; uma conta XMPP segue como um novo dispositivo da conta, com seus contatos e conversas; uma conta Matrix é solta neste celular, e o espaço entra de novo como um novo dispositivo; a chave de segurança dele abre as mensagens de antes. Veja [Backups](#backup).",
  "**Matrix voice messages show their waveform, and Nostr answers can be photos**: a voice message sent in a Matrix chat carries its waveform, which Element draws, and one that comes with a waveform shows it under Play; in a Nostr chat, a photo, file or voice message sent while a message shows over the message box answers it. See [Matrix](#matrix) and [Chats with other Nostr apps](#nostr-chats).":
    "**As mensagens de voz do Matrix mostram sua forma de onda, e as respostas no Nostr podem ser fotos**: uma mensagem de voz enviada numa conversa Matrix leva sua forma de onda, que o Element desenha, e uma que chega com forma de onda a mostra abaixo de Reproduzir; numa conversa Nostr, uma foto, um arquivo ou uma mensagem de voz enviada enquanto uma mensagem aparece acima do campo a responde. Veja [Matrix](#matrix) e [Conversas com outros apps Nostr](#nostr-chats).",
  "**Group calls in XMPP groups**: in a private XMPP group, start a voice or video call, answer one that rings, or join one going on, together with people who use Dino. See [XMPP](#xmpp).":
    "**Chamadas de grupo nos grupos XMPP**: num grupo privado XMPP, inicie uma chamada de voz ou de vídeo, atenda uma que toca, ou entre numa que está acontecendo, junto com pessoas que usam o Dino. Veja [XMPP](#xmpp).",
  '**A call to a slow phone rings in full**: the caller now waits up to a minute and a quarter for the other phone to say it rings, and then 45 seconds from then, so a call that reached it late no longer rings there only to stop at once; and the phone called reads a call before anything it has to send, and waits for calls again at once after its network changes. See [Chat through a relay](#relay).':
    '**Uma chamada para um telefone lento toca inteira**: quem chama agora espera até um minuto e um quarto que o outro telefone diga que está tocando, e depois 45 segundos a partir daí, para que uma chamada que chegou tarde não toque mais só para parar logo em seguida; e o telefone chamado lê uma chamada antes de tudo o que tem para enviar, e volta a esperar chamadas logo após uma troca de rede. Veja [Conversar por um relay](#relay).',
  "**The web app and the computer reach Matrix, XMPP and Nostr servers over HTTPS**: their page policy allowed only WebSocket connections, so Matrix sign-in, XMPP server discovery and file sharing, and Nostr files and name lookups failed there. They work now. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**O app web e o computador alcançam servidores Matrix, XMPP e Nostr por HTTPS**: a política da página deles só permitia conexões WebSocket, então o login no Matrix, a descoberta do servidor XMPP e o envio de arquivos, e os arquivos e as buscas de nomes do Nostr falhavam lá. Agora funcionam. Veja [Matrix](#matrix), [XMPP](#xmpp) e [Conversas com outros apps Nostr](#nostr-chats).",
  // 3.4.2
  '**A message sent as a chat opens waits for it**, marked Sending…, and goes as soon as the chat is open, never saying that Erevos cannot encrypt.':
    '**Uma mensagem enviada enquanto uma conversa abre espera por ela**, marcada Enviando…, e vai assim que a conversa abre, sem dizer que o Erevos não pode criptografar.',
  '**What you read as a chat opens stays read**: the home screen no longer counts it as new.':
    '**O que você lê enquanto uma conversa abre fica lido**: a tela inicial não conta mais como novo.',
  '**No question from Samsung about its sharing**: on a Samsung phone, Wi-Fi Aware and the Wi-Fi with phones nearby stay off until you turn them on. See [Chat with a nearby phone](#nearby).':
    '**Nenhuma pergunta da Samsung sobre o compartilhamento dela**: em um celular Samsung, o Wi-Fi Aware e a rede Wi-Fi com celulares por perto ficam desligados até você ligá-los. Veja [Conversar com um celular por perto](#nearby).',
  '**The SMS field keeps its width on a small screen**: Photo and Send beside it are round buttons, as in a chat.':
    '**O campo do SMS mantém a largura numa tela pequena**: Foto e Enviar ao lado são botões redondos, como numa conversa.',
  // 3.4.1
  '**Send answers at once**: a short buzz as you press it, the field empties and the message shows, marked Sending…, so it never goes twice.':
    '**Enviar responde na hora**: uma vibração curta ao tocar, o campo se esvazia e a mensagem aparece, marcada Enviando…, então nunca sai duas vezes.',
  '**The screen no longer stays pushed up** after the keyboard closed behind a sheet, a dialog or another app.':
    '**A tela não fica mais empurrada para cima** depois que o teclado se fechou atrás de um painel, de um diálogo ou de outro app.',
  '**Importing a chat with its photos no longer freezes Erevos**: the screen moves while the files come in, says what share of them is in, and **Cancel** stops it. A chat moved into hidden chats takes the chats imported into it along. See [Imported chats](#import).':
    '**Importar uma conversa com suas fotos não trava mais o Erevos**: a tela responde enquanto os arquivos chegam, diz que parte já chegou e **Cancelar** interrompe. Uma conversa movida para as conversas ocultas leva junto as conversas importadas nela. Veja [Conversas importadas](#import).',
  // 3.4.0
  '**Your relay proves its own key**: every connection to it starts with a check only the relay holding that key can pass, so no one in between can pass for it. Once it has, Erevos never reaches it without the check. Your relay needs an update for it.':
    '**O seu relay prova a própria chave**: cada conexão com ele começa com uma verificação em que só passa o relay que tem essa chave, então ninguém no meio pode se passar por ele. Depois que ele prova uma vez, o Erevos nunca mais se conecta a ele sem a verificação. Para isso, o seu relay precisa de uma atualização.',
  '[Transparency](#transparency), a new part of the guide: what the server behind Erevos keeps and for how long, what it does not keep, and who else sees something.':
    '[Transparência](#transparency), uma nova parte do guia: o que o servidor por trás do Erevos guarda e por quanto tempo, o que ele não guarda e quem mais vê alguma coisa.',
  "**What's new**: this list, in Settings → General, by version.": '**Novidades**: esta lista, em Configurações → Geral, por versão.',
  "**Nothing shows behind a chat's PIN**: none of the messages of a chat locked with a PIN is drawn until its PIN is typed, and with glass, a wallpaper or a style's own scene, the PIN screen is a dense frost that lets nothing through.":
    "**Nada aparece atrás do PIN de uma conversa**: nenhuma mensagem de uma conversa bloqueada com um PIN é mostrada antes de o PIN ser digitado, e com vidro, um papel de parede ou um estilo com cena própria, a tela do PIN é um fosco denso que não deixa ver nada.",
  "**A group video call from the top of the group**: a blue camera beside the green handset, as in a contact's chat.":
    "**Videochamada de grupo no topo do grupo**: uma câmera azul ao lado do fone verde, como na conversa com um contato.",
  "**A relay queue for each contact**: each contact writes to a queue only they know, so the relay cannot tell that two contacts write to the same phone, and deleting or blocking someone deletes only theirs. Your relay needs an update for it.":
    "**Uma fila do relay para cada contato**: cada contato escreve numa fila que só ele conhece, então o relay não consegue saber que dois contatos escrevem para o mesmo telefone, e apagar ou bloquear alguém apaga só a dele. Seu relay precisa ser atualizado para isso.",
  "**Hidden chats, more like the others**: they close after 30 seconds in the background, not at once, and never during a call or while you pick a photo or a file; while open, a message plays its sound, and link previews have a switch of their own there. See [Hidden chats](#hidden).":
    "**As conversas ocultas, mais como as outras**: fecham após 30 segundos em segundo plano, não de imediato, e nunca durante uma chamada nem enquanto você escolhe uma foto ou um arquivo; abertas, uma mensagem toca o seu som, e as pré-visualizações de links têm ali um interruptor próprio. Veja [Conversas ocultas](#hidden).",
  "**Hidden chats that receive while closed**: a switch at the top of each place, on for new places, has them receive as your other chats do: their contacts see at once that a message came, a notice says only \"New message\", and a call rings with no name. See [Hidden chats](#hidden).":
    "**Conversas ocultas que recebem quando fechadas**: um interruptor no topo de cada lugar, ligado nos lugares novos, faz com que recebam como as suas outras conversas: os contatos delas veem na hora que uma mensagem chegou, um aviso diz só “Nova mensagem”, e uma chamada toca sem nome. Veja [Conversas ocultas](#hidden).",
  "**Hidden chats wait and import too**: what cannot go now waits, marked Waiting, and goes by itself through their relay; Send later works there as in your other chats; and a chat from Telegram, WhatsApp or Viber can be imported into a hidden chat, kept only there. See [Hidden chats](#hidden).":
    "**As conversas ocultas também aguardam e importam**: o que não pode sair agora aguarda, marcado “Aguardando”, e sai sozinho pelo relay delas; “Enviar mais tarde” funciona ali como nas suas outras conversas; e uma conversa do Telegram, WhatsApp ou Viber pode ser importada para uma conversa oculta, guardada só ali. Veja [Conversas ocultas](#hidden).",
  "**Hidden chats listed like your chats**: they open on a list as the home screen's, with what was said last and how many are not read, and each place has a Chat with myself of its own at its top. See [Hidden chats](#hidden).":
    "**As conversas ocultas em lista como as suas conversas**: abrem numa lista como a da tela inicial, com o que foi dito por último e quantas não foram lidas, e cada posição tem no topo a sua própria Conversa comigo. Veja [Conversas ocultas](#hidden).",
  "**More in hidden chats**: with Receive while closed on, what comes to them through Nostr is read while they are closed too; and there a contact can be added from a photo of their QR code, and a hidden contact given a photo. See [Hidden chats](#hidden).":
    "**Mais nas conversas ocultas**: com Receber quando fechadas, o que lhes chega pelo Nostr também é lido enquanto estão fechadas; e lá é possível adicionar um contato a partir de uma foto do código QR dele e dar uma foto a um contato oculto. Veja [Conversas ocultas](#hidden).",
  "**Hidden chats with no relay**: as your other chats, they can begin through Nostr only: their contact link and QR code say where they read there, and texts and reactions go there. See [Hidden chats](#hidden).":
    "**Conversas ocultas sem relay**: como as suas outras conversas, podem começar só pelo Nostr: o link de contato e o código QR delas dizem onde leem lá, e textos e reações vão para lá. Veja [Conversas ocultas](#hidden).",
  "**Groups in hidden chats**: under their list, New group makes a group with their contacts; it lists among their chats, goes through their relay only, and is read while they are closed if Receive while closed is on. See [Hidden chats](#hidden).":
    "**Grupos nas conversas ocultas**: abaixo da lista delas, Novo grupo cria um grupo com os contatos delas; ele aparece entre as conversas delas, passa só pelo relay delas e é lido enquanto estão fechadas se Receber quando fechadas estiver ativado. Veja [Conversas ocultas](#hidden).",
  "**No test version line**: the home screen no longer ends saying this is a test version. The guide still says exactly what is protected, and that nothing has been audited yet. See [What is protected today](#privacy).":
    "**Sem a linha de versão de teste**: a tela inicial não termina mais dizendo que esta é uma versão de teste. O guia continua dizendo exatamente o que está protegido, e que nada foi auditado ainda. Veja [O que está protegido hoje](#privacy).",
  "**The contacts menu in hidden chats**: their Contacts has a menu again, with what is theirs only: a .vcf file imported into them, their contacts saved as a .vcf file, and a contact's QR code read from a photo. An Erevos ID typed there adds them to the hidden chats. See [Contacts](#contacts).":
    "**O menu de contatos nas conversas ocultas**: os Contatos delas voltam a ter um menu, só com o que é delas: um arquivo .vcf importado nelas, seus contatos salvos como arquivo .vcf e o código QR de um contato lido de uma foto. Um ID do Erevos digitado ali adiciona a pessoa às conversas ocultas. Veja [Contatos](#contacts).",
  // 3.3.2
  '**The plain call button for more contacts**: the orange keypad at the top of a contact’s chat also takes the number of a contact you connected them to (**Connect to one of my contacts**), the mobile number first.':
    '**O botão de chamada comum para mais contatos**: o teclado laranja no topo da conversa de um contato também usa o número do contato a que você o vinculou (**Vincular a um dos meus contatos**), primeiro o celular.',
  // 3.3.1
  '**Viber chats can be imported**: from the HTML file of the Android app Backup Text for Viber, words only.':
    '**Conversas do Viber podem ser importadas**: do arquivo HTML do app Android Backup Text for Viber, só os textos.',
  // 3.3.0
  '**Start without a relay, through Nostr**: **Start without a relay** on New chat. Texts, stickers, reactions, edits and the delivered and read marks go through Nostr over Tor. Photos, voice messages, files and calls still need a relay or a phone nearby.':
    '**Começar sem relay, pelo Nostr**: **Começar sem relay** em Nova conversa. Textos, figurinhas, reações, edições e as marcas de entregue e lida vão pelo Nostr, via Tor. Fotos, mensagens de voz, arquivos e chamadas ainda precisam de um relay ou de um celular por perto.',
  '**The relay comes by itself**: whoever has a relay that invites sends a contact with no relay an invite once, inside the chat, and the other phone takes it by itself.':
    '**O relay chega sozinho**: quem tem um relay que faz convites envia uma vez um convite a um contato sem relay, dentro da conversa, e o outro celular o aceita sozinho.',
  '**Told when a new version is out** (Android): once a day Erevos asks LPHL’s server, then shows a pinned Erevos row and a notice, only for a version the release computer signed. It turns off in Settings → General → Updates.':
    '**Aviso quando sai uma versão nova** (Android): uma vez por dia o Erevos pergunta ao servidor do LPHL e então mostra uma linha fixada do Erevos e uma notificação, só para uma versão assinada pelo computador de versões. Dá para desativar em Configurações → Geral → Atualizações.',
  '**Lock a chat with a PIN**: Details → Lock with a PIN, for chats and groups. Nothing of it shows in search, starred messages or imports. In hidden chats it asks for no PIN.':
    '**Bloquear uma conversa com um PIN**: Detalhes → Bloquear com um PIN, para conversas e grupos. Nada dela aparece na busca, nas mensagens favoritas nem nas importações. Nas conversas ocultas, não pede PIN.',
  '**A new handset** on the green tiles: Phone, and the call in a chat.': '**Um novo ícone de fone** nos blocos verdes: Telefone, e a chamada em uma conversa.',
  '**A new New chat screen**: How you connect now at the top, three large cards for a phone without a relay (I have an invite, Sign in with LPHL, Start without a relay), and the technical part under For advanced users.':
    '**Uma nova tela de Nova conversa**: Como você se conecta agora no topo, três cartões grandes para um celular sem relay (Tenho um convite, Entrar com LPHL, Começar sem relay) e a parte técnica em Para usuários avançados.',
  '**Nostr steadier through Tor**: each Nostr relay has its own way through Tor, and after a failure it tries a new exit. A clearer error on the Nostr screen.':
    '**Nostr mais estável pelo Tor**: cada relay Nostr tem o próprio caminho pelo Tor e, depois de uma falha, tenta uma nova saída. Um erro mais claro na tela do Nostr.',
  '**When the connection to the relay drops** while Erevos waits on it, Erevos notices and connects again, where it stayed stuck before.':
    '**Quando a conexão com o relay cai** enquanto o Erevos espera por ele, o Erevos percebe e se conecta de novo, onde antes ficava travado.',
  '**Invite by SMS** (Android): on a phone contact’s card, for one person, for 2 days. The link opens a page that offers Erevos (the APK for Android, the web app for an iPhone or a computer), then opens the invite. The QR code and Share the invite stay as they were.':
    '**Convidar por SMS** (Android): no cartão de um contato do celular, para uma pessoa, por 2 dias. O link abre uma página que oferece o Erevos (o APK para Android, o app web para iPhone ou computador) e depois abre o convite. O código QR e Compartilhar o convite continuam como estavam.',
  '**Fixes to the SMS invite**: a link copied as /i/#… works too, an older web app opens the invite as well, and on iOS 26 it says Share is under •••.':
    '**Correções no convite por SMS**: um link copiado como /i/#… também funciona, um app web mais antigo também abre o convite e, no iOS 26, avisa que Compartilhar fica em •••.',
  '**A phone call button** in Erevos chats and SMS chats.': '**Um botão de chamada telefônica** nas conversas do Erevos e nas conversas por SMS.',
  // 3.2.1
  '**Edit a message** you sent, up to a day after: to contacts, groups and linked devices, with Edited beside the time.':
    '**Editar uma mensagem** que você enviou, até um dia depois: para contatos, grupos e dispositivos conectados, com Editada ao lado do horário.',
  '**Nostr says what it did**: Sent through Nostr, and on the Nostr screen what each relay did last.':
    '**O Nostr diz o que fez**: Enviada pelo Nostr, e na tela do Nostr o que cada relay fez por último.',
  '**Coloured call buttons** at the top of a chat: video blue, voice green.': '**Botões de chamada coloridos** no topo de uma conversa: vídeo azul, voz verde.',
  // 3.2.0
  'Arrows to the start and the end of a chat; earlier messages come by themselves as you scroll.':
    'Setas para o início e o fim de uma conversa; as mensagens mais antigas carregam sozinhas conforme você rola.',
  'Chats imported from Telegram and WhatsApp look like Erevos messages: bubbles, days, photos, voice messages, search.':
    'As conversas importadas do Telegram e do WhatsApp aparecem como mensagens do Erevos: balões, dias, fotos, mensagens de voz, busca.',
  'Dogs instead of cats in the stickers.': 'Cachorros em vez de gatos nas figurinhas.',
  'Screenshots: a switch in Settings → Privacy and security.': 'Capturas de tela: uma opção em Configurações → Privacidade e segurança.',
  'Hidden chats from New chat: hold it for a second.': 'Conversas ocultas a partir de Nova conversa: mantenha pressionado por um segundo.',
  'Coloured tiles on the home screen: Phone green, Contacts violet, the lock orange.': 'Blocos coloridos na tela inicial: Telefone verde, Contatos roxo, o cadeado laranja.',
  '**Chat with myself**, always first, and **Remind me**, the orange bell.': '**Conversa comigo**, sempre em primeiro, e **Lembrar-me**, o sino laranja.',
  '**Media, links and files** in a chat’s Details, with a calendar and Go to a day.':
    '**Mídia, links e arquivos** nos Detalhes de uma conversa, com um calendário e Ir para um dia.',
  'Import a chat from inside the chat: Details → Imported chats.': 'Importar uma conversa de dentro da própria conversa: Detalhes → Conversas importadas.',
  'A closed space can say that a message came while another space is open.': 'Um espaço fechado pode avisar que chegou uma mensagem enquanto outro espaço está aberto.',
  'The message menu says when a message went or came through Nostr.': 'O menu da mensagem diz quando uma mensagem foi ou veio pelo Nostr.',
  '**Support Erevos**: Liberapay, PayPal, Monero, Bitcoin.': '**Apoiar o Erevos**: Liberapay, PayPal, Monero, Bitcoin.',
  'Who makes Erevos and why, in About Erevos; the guide says why everywhere.': 'Quem faz o Erevos e por quê, em Sobre o Erevos; o guia explica o porquê em toda parte.',
  // 3.1.2
  '**Settings in 8 groups**, with a search: General, Appearance, Notifications, Privacy and security, Relay and networks, Phone and SMS, Data and devices, For testing. The home screen’s ⋯ keeps only the places, and Settings last.':
    '**Configurações em 8 grupos**, com busca: Geral, Aparência, Notificações, Privacidade e segurança, Relay e redes, Telefone e SMS, Dados e dispositivos, Para testes. O ⋯ da tela inicial fica só com os lugares, e Configurações por último.',
  // 3.1.1
  'Check for updates says what stopped an update.': 'Procurar atualizações diz o que impediu uma atualização.',
  'Invite someone is not made from a token for all; it asks you to sign in to the relay first.':
    'Convidar alguém não usa mais um token compartilhado; antes, pede que você entre no relay.',
  'The relay’s token for all becomes a token of the phone’s own, by itself (needs the relay updated).':
    'O token compartilhado do relay vira sozinho um token próprio do celular (precisa do relay atualizado).',
  'A relay that refuses through Tor says why.': 'Um relay que recusa pelo Tor diz por quê.',
  // 3.1.0
  'Less battery in the background: the relay, Tor and the nearby radios.': 'Menos bateria em segundo plano: o relay, o Tor e os rádios para celulares por perto.',
  'Erevos no longer closes when you make a sticker from a photo.': 'O Erevos não fecha mais quando você faz uma figurinha a partir de uma foto.',
  'Hidden chats’ notices are right.': 'As notificações das conversas ocultas estão corretas.',
  'Hidden chats by holding New chat.': 'Conversas ocultas mantendo Nova conversa pressionado.',
  'A search for contacts on the Phone.': 'Busca de contatos no Telefone.',
  'New chat shows first how to add a contact.': 'Nova conversa mostra primeiro como adicionar um contato.',
  'A call shows over the screen saver, and the screen wakes.': 'Uma chamada aparece sobre o protetor de tela, e a tela acende.',
  'Erevos in other apps’ Share.': 'O Erevos no Compartilhar dos outros apps.',
  'A sound for every new message, also while Erevos shows.': 'Um som para cada mensagem nova, também com o Erevos na tela.',
  'The SMS settings say right what holding does.': 'As configurações de SMS dizem corretamente o que acontece ao manter pressionado.',
  // 3.0.0
  'Each icon opens what it names: Erevos, SMS, Phone, Contacts, the widget.': 'Cada ícone abre o que o nome diz: Erevos, SMS, Telefone, Contatos, o widget.',
  '**Messages through Tor by default**: Messages, Everything or Nothing.': '**Mensagens pelo Tor por padrão**: Mensagens, Tudo ou Nada.',
  '**Texts through Nostr**: three public relays, through Tor, with your own relay as backup after 5 minutes.':
    '**Textos pelo Nostr**: três relays públicos, pelo Tor, com o seu próprio relay como reserva depois de 5 minutos.',
  // 2.0.3
  'One invite for everything: the relay and the contact together.': 'Um convite para tudo: o relay e o contato juntos.',
  'Spam rules for senders and numbers abroad, with the reason.': 'Regras de spam para remetentes e números do exterior, com o motivo.',
  '480 stickers in 20 sets.': '480 figurinhas em 20 pacotes.',
  'Lighter chats on older phones; QR codes at once.': 'Conversas mais leves em celulares antigos; códigos QR na hora.',
  'Copy code for one-time codes in SMS.': 'Copiar código para os códigos de uso único nos SMS.',
  'Locked, Erevos keeps receiving.': 'Bloqueado, o Erevos continua recebendo.',
  'Faster contacts; the hidden chats’ notice counts only messages.': 'Contatos mais rápidos; a notificação das conversas ocultas conta só mensagens.',
  'The relay tries every address: push, other relays, the LPHL sign-in.': 'O relay tenta todos os endereços: push, outros relays, o login do LPHL.',
  // 2.0.2
  'Swiping on the tabs only changes the tab.': 'Deslizar nas abas só troca de aba.',
  'The icons fill the launcher’s shape.': 'Os ícones preenchem o formato do launcher.',
  // 2.0.1
  'Coloured icons (Erevos red, Phone green, SMS blue, Contacts violet) and a new SMS icon.':
    'Ícones coloridos (Erevos vermelho, Telefone verde, SMS azul, Contatos roxo) e um novo ícone de SMS.',
  'A colour for each icon, and the order of the widget’s buttons.': 'Uma cor para cada ícone, e a ordem dos botões do widget.',
  'Swipe to go back, and between tabs.': 'Deslizar para voltar, e entre as abas.',
  // 2.0.0
  'An update of the WebView no longer closes Erevos.': 'Uma atualização do WebView não fecha mais o Erevos.',
  'Deleting or blocking a contact gives you a new queue on the relay.': 'Apagar ou bloquear um contato dá a você uma nova fila no relay.',
  'A new contact can take the name of a contact on the phone.': 'Um novo contato pode usar o nome de um contato do celular.',
  '**Sign in to the relay with LPHL**, and **invites to the relay**.': '**Entrar no relay com LPHL**, e **convites para o relay**.',
  'Permissions in the web app, and more on Android; the web app’s notice says how many came.':
    'Permissões no app web, e mais no Android; a notificação do app web diz quantas mensagens chegaram.',
  'Hidden chats can ring calls while they are closed.': 'As conversas ocultas podem tocar as chamadas enquanto estão fechadas.',
  'New keys every month in chats, every week in groups.': 'Chaves novas todo mês nas conversas, toda semana nos grupos.',
  'Linked devices work with the phone off.': 'Os dispositivos conectados funcionam com o celular desligado.',
  'A new chat screen; QR codes from a photo; the Phone for small screens.': 'Uma nova tela de conversa; códigos QR a partir de uma foto; o Telefone para telas pequenas.',
  'Add as contact inside a group.': 'Adicionar como contato dentro de um grupo.',
  'Stickers in sets, moving, and your own.': 'Figurinhas em pacotes, animadas, e as suas próprias.',
  'SMS inside the Erevos chat.': 'SMS dentro da conversa do Erevos.',
  'Android updates need the release computer’s signature.': 'As atualizações para Android precisam da assinatura do computador de versões.',
  'An F-Droid build; Serbo-Croatian; new version numbers.': 'Uma versão para o F-Droid; servo-croata; novos números de versão.',
  'Much for security: Argon2id, messages encrypted for the relay too, a token for each phone, no link starts a call.':
    'Muito para a segurança: Argon2id, mensagens criptografadas também para o relay, um token para cada celular, nenhum link inicia uma chamada.',
  // 0.1.16
  'Imports from Telegram and WhatsApp bring photos, videos, voice messages and files.': 'As importações do Telegram e do WhatsApp trazem fotos, vídeos, mensagens de voz e arquivos.',
  'A phone without a relay talks through a place on a contact’s relay.': 'Um celular sem relay se comunica por um lugar no relay de um contato.',
  // 0.1.14
  'Back to my chats, for hidden chats.': 'Voltar para minhas conversas, para as conversas ocultas.',
  'Erevos receives and rings even after you swipe it away from the recent apps.': 'O Erevos recebe e toca mesmo depois que você o fecha nos apps recentes.',
  // 0.1.12
  'Hidden chats can say a message came.': 'As conversas ocultas podem avisar que chegou uma mensagem.',
  'Fixes: menus, QR codes from a photo, Bluetooth on Android 17, long lists.': 'Correções: menus, códigos QR a partir de uma foto, Bluetooth no Android 17, listas longas.',
  // 0.1.11
  'The Phone without the password, if you allow it; a home screen widget; an SMS and Erevos filter.':
    'O Telefone sem a senha, se você permitir; um widget para a tela inicial; um filtro de SMS e Erevos.',
  // 0.1.10
  'Links wait for the password; Phone and Contacts icons; the Erevos ID on a contact.': 'Os links esperam a senha; ícones de Telefone e Contatos; o ID do Erevos em um contato.',
  // 0.1.8
  '61 new features: 5 new languages, linked devices, public groups, replies, reactions, polls, send later, Erevos as the phone and contacts app, Tor bridges, the fingerprint, Windows and more.':
    '61 recursos novos: 5 idiomas novos, dispositivos conectados, grupos públicos, respostas, reações, enquetes, enviar mais tarde, o Erevos como app de telefone e de contatos, pontes do Tor, a impressão digital, Windows e mais.',
  // 0.1.7 to 0.1.2
  'SMS notices in the background.': 'Notificações de SMS em segundo plano.',
  'The web app comes out with every release.': 'O app web sai junto com cada versão.',
  'Greek in the whole app.': 'Grego no app inteiro.',
  'Web Push in the web app.': 'Web Push no app web.',
  'The first signed Android release: encrypted chats, calls, groups, hidden chats, backups, imports, and phones nearby without the internet.':
    'A primeira versão assinada para Android: conversas criptografadas, chamadas, grupos, conversas ocultas, backups, importações e celulares por perto sem internet.',
  "**Two new sticker sets of 24 moods**: **Tux**, the Linux penguin as he is drawn, and **Aikido**, an aikidoka in keikogi and a wide hakama, who also bows, sits in seiza and rolls.":
    "**Dois novos conjuntos de figurinhas com 24 humores**: **Tux**, o pinguim do Linux tal como é desenhado, e **Aikido**, um aikidoka de keikogi e hakama largo, que também se curva, senta-se em seiza e rola.",
  "**A new sticker set, Takis**: a caricature in a dark suit and a purple tie with dots, in 24 moods that move.":
    "**Um novo conjunto de figurinhas, Takis**: uma caricatura de terno escuro e gravata roxa de bolinhas, em 24 humores que se mexem.",
  "**Photos, files and voice messages with no relay**: when there is no relay between you and your contact and they read on Nostr, a voice message goes through Nostr like a text, a photo up to 3 MB in pieces, and a larger photo, a video or another file, up to 20 MB, to an encrypted file server (Blossom), all through Tor. See [Through Nostr](#nostr).":
    "**Fotos, arquivos e mensagens de voz sem relay**: quando não há relay entre você e o seu contato e ele lê no Nostr, uma mensagem de voz vai pelo Nostr como um texto, uma foto de até 3 MB em pedaços, e uma foto maior, um vídeo ou outro arquivo, de até 20 MB, para um servidor de arquivos cifrado (Blossom), tudo pelo Tor. Veja [Pelo Nostr](#nostr).",
  "**More battery saved in the background, if you choose**: under Settings → Notifications → In the background, Only the waste stays the default; And nearby phones also turns off the radios for phones nearby while Erevos is in the background; And sleep also lets the phone sleep, so Erevos looks at your relay about once a minute and a message or a call can be a minute or two late. Android only. See [Chat through a relay](#relay).":
    "**Mais bateria poupada em segundo plano, se você escolher**: em Configurações → Notificações → Em segundo plano, Só o desperdício continua sendo o padrão; E os celulares por perto desliga também os rádios para celulares por perto enquanto o Erevos está em segundo plano; E o sono deixa também o celular dormir, de modo que o Erevos olha o seu relay cerca de uma vez por minuto e uma mensagem ou uma chamada pode chegar um ou dois minutos atrasada. Só no Android. Veja [Conversar por um relay](#relay).",
  "**A contact you delete no longer comes back from an old ask**: in a group, a member you asked for their contact link, or who asked for yours, and whom you then deleted as a contact before Erevos looked at the relay again, could be added again by that old ask. Deleting them now lets go of it at once. See [Group chats](#groups).":
    "**Um contato apagado não volta mais por um pedido antigo**: num grupo, um membro cujo link de contato você pediu, ou que pediu o seu, e que depois você apagou como contato antes de o Erevos olhar o relay de novo, podia ser adicionado outra vez por esse pedido antigo. Agora apagá-lo larga o pedido na hora. Veja [Conversas em grupo](#groups).",
  "**Every message says which way it went**: hold a message and its menu says whether it went or came through the relay, through Nostr, to a phone nearby or over LoRa. Messages from before say nothing. See [Through Nostr](#nostr).":
    "**Cada mensagem diz por onde foi**: segure uma mensagem e o menu dela diz se foi ou veio pelo relay, pelo Nostr, por um telefone por perto ou por LoRa. As mensagens de antes não dizem nada. Veja [Pelo Nostr](#nostr).",
  "**The spam filter reads words as they look**: a scam text that swaps a letter for a look-alike of another alphabet, or hides a mark that shows nothing inside a word, no longer gets past it. See [SMS](#sms).":
    "**O filtro de spam lê as palavras como elas aparecem**: um SMS de golpe que troca uma letra por uma parecida de outro alfabeto, ou esconde numa palavra uma marca que não se vê, já não o engana. Veja [SMS](#sms).",
  "**Media, links and files in groups too**: in a group's details, a list of its photos, videos, voice messages, music, files and links, each kind apart under its months, with a calendar, as in a contact's chat. A tap opens or plays; held, each goes to its message. See [Group chats](#groups).":
    "**Mídia, links e arquivos também nos grupos**: nos detalhes de um grupo, uma lista das suas fotos, vídeos, mensagens de voz, músicas, arquivos e links, cada tipo à parte sob os seus meses, com um calendário, como na conversa de um contato. Um toque abre ou toca; segurado, cada um vai até a sua mensagem. Veja [Conversas em grupo](#groups).",
  "**A relay restart no longer brings a false notice**: after your relay restarted, a hidden chat or a closed space said New message once more for messages it had told of already. Your relay needs an update for it. See [Hidden chats](#hidden).":
    "**Um reinício do relay não traz mais um aviso falso**: depois que o seu relay reiniciava, uma conversa oculta ou um espaço fechado dizia de novo Nova mensagem por mensagens de que já tinha avisado. O seu relay precisa de uma atualização para isso. Veja [Conversas ocultas](#hidden).",
  "**Backups to your server through Tor**: on Android, automatic backups sent to your own server now follow the space's choice under Settings → Relay and networks → Tor, as Matrix does, so with Tor the server no longer sees where you are. To a server too says when they go through Tor. See [Backups](#backup).":
    "**Backups para o seu servidor pelo Tor**: no Android, os backups automáticos enviados ao seu próprio servidor agora seguem a escolha do espaço em Configurações → Relay e redes → Tor, como o Matrix, então com Tor o servidor não vê mais onde você está. Também para um servidor diz quando vão pelo Tor. Veja [Backups](#backup).",
  "**Restore a backup straight from your server**: Restore from a server, under Backups, lists the backups on your server, newest first, and opens the one you choose with its password, with no download by hand, on a new phone too. See [Backups](#backup).":
    "**Restaure um backup direto do seu servidor**: Restaurar de um servidor, em Backups, mostra os backups no seu servidor, os mais recentes primeiro, e abre o que você escolher com a senha dele, sem baixar à mão, num celular novo também. Veja [Backups](#backup).",
  "**Backups to your server from a computer and the web app too**: in the desktop app, automatic backups go to your WebDAV server as on Android; in the web app, Send a backup now sends one there, with a server that lets the web app in. Both can restore from it. Not through Tor. See [Backups](#backup).":
    "**Backups para o seu servidor também do computador e do web app**: no app para computador, os backups automáticos vão para o seu servidor WebDAV como no Android; no web app, Enviar um backup agora envia um para lá, com um servidor que deixe o web app entrar. Os dois podem restaurar a partir dele. Não pelo Tor. Veja [Backups](#backup).",
  "**Check a contact in person with QR codes**: under Safety number in a chat's details, each phone shows a code; take a photo of the code on the other phone, and they of yours. When it matches, the contact is marked Checked in person. Nothing is sent. See [Chat through a relay](#relay).": "**Confira um contato pessoalmente com códigos QR**: em Número de segurança, nos detalhes de uma conversa, cada celular mostra um código; tire uma foto do código no outro celular, e a pessoa do seu. Quando bate, o contato fica marcado como Conferido pessoalmente. Nada é enviado. Veja [Conversar por um relay](#relay).",
  "**Up to three home relays**: under Settings → Relay and networks → Home relay, Add another home relay gives a space up to two more, each with a queue of its own. Your contact link and your messages name them in order, and contacts try each while the ones before cannot be reached. See [Home relay](#home-relay).": "**Até três relays de casa**: em Configurações → Relay e redes → Relay de casa, Adicionar outro relay de casa dá a um espaço até mais dois, cada um com sua própria fila. Seu link de contato e suas mensagens citam todos em ordem, e os contatos tentam cada um enquanto os anteriores não respondem. Veja [Relay de casa](#home-relay).",
  "**Introduce two of your contacts**: in a contact's chat details, Introduce to a contact asks them and another contact of yours, each in your chat with them. Only if both say yes do they become contacts, and neither learns whether the other said no. See [Chat through a relay](#relay).": "**Apresente dois dos seus contatos**: nos detalhes da conversa de um contato, Apresentar a um contato pergunta a ele e a outro contato seu, cada um na sua conversa com ele. Só se os dois disserem sim eles viram contatos, e nenhum fica sabendo se o outro disse não. Veja [Conversar por um relay](#relay).",
  "**Bluetooth that cannot be followed**: the random number your phone sends out over Bluetooth for phones nearby to find it changed only when Erevos started again; it now changes every nine to twelve minutes, so someone listening cannot follow your phone from place to place by it. Older Erevos phones still find yours. See [Chat with a nearby phone](#nearby).": "**Bluetooth que não dá para seguir**: o número aleatório que seu celular emite por Bluetooth para os celulares por perto o acharem só mudava quando o Erevos reiniciava; agora muda a cada nove a doze minutos, então quem escuta não consegue seguir seu celular de um lugar a outro por ele. Celulares com um Erevos mais antigo ainda acham o seu. Veja [Conversar com um celular por perto](#nearby).",
  "**Hidden chats show at once**: as the PIN opens them, their chats and contacts show at once, to read, while what they were receiving in the background ends; before, that could hold them back a long while, as it may go through Tor. See [Hidden chats](#hidden).": "**As conversas ocultas aparecem na hora**: assim que o PIN as abre, suas conversas e contatos aparecem na hora, para ler, enquanto termina o que elas recebiam em segundo plano; antes, isso podia atrasá-las por muito tempo, pois pode passar pelo Tor. Veja [Conversas ocultas](#hidden).",
  "**Your backup password in pieces with friends**: under Settings → Data and devices → Backup pieces, give pieces of it to 3 to 5 contacts; any 2 or 3 of them give it back, one alone shows nothing. Each goes inside the encryption of your chat with them and only their Erevos keeps it; your phone keeps none. See [Backup pieces with friends](#backup-pieces).": "**A senha dos seus backups em partes com amigos**: em Configurações → Dados e dispositivos → Partes do backup, dê partes dela a 3 a 5 contatos; quaisquer 2 ou 3 a devolvem, uma sozinha não mostra nada. Cada uma vai dentro da criptografia da sua conversa com eles e só o Erevos deles a guarda; seu celular não guarda nenhuma. Veja [Partes do backup com amigos](#backup-pieces).",
  "**Panic button**: under Settings → Privacy and security → Panic button, wipe everything Erevos keeps here with one tap, on Android and in the web app. On Android, a panic app such as Ripple can do it too, but only the one you say yes to, checked by its signature. See [Panic button](#panic).": "**Botão de pânico**: em Configurações → Privacidade e segurança → Botão de pânico, apague com um toque tudo o que o Erevos guarda aqui, no Android e no app web. No Android, um app de pânico como o Ripple também pode fazer isso, mas só aquele a que você disser sim, conferido pela assinatura dele. Veja [Botão de pânico](#panic).",
  "**Erevos to a phone nearby, with no internet**: under Settings → General → Give Erevos to a phone nearby, this phone serves its Erevos over the same Wi-Fi or its hotspot for ten minutes, with a QR code. A phone without Erevos downloads it in the browser; one with an older Erevos takes it under Updates → From a phone nearby, which installs it only when it is Erevos, signed as that one is. See [Erevos to a phone nearby](#give-app).": "**O Erevos para um telefone próximo, sem internet**: em Configurações → Geral → Dar o Erevos a um telefone próximo, este telefone serve o Erevos dele pela mesma Wi-Fi ou pelo hotspot dele por dez minutos, com um código QR. Um telefone sem o Erevos o baixa no navegador; um com um Erevos mais antigo o recebe em Atualizações → De um telefone próximo, que só o instala se for o Erevos, assinado como aquele. Veja [O Erevos para um telefone próximo](#give-app).",
  "**Hidden chats with phones nearby**: while hidden chats are open, or receive while closed, they reach a contact's phone nearby over Bluetooth, Wi-Fi Aware, Wi-Fi Direct or the same Wi-Fi, with no internet, as your other chats do. The space never learns that a hidden contact is near, and nothing on the air tells their messages from the space's; other phones never carry them, and they never go over LoRa or by SMS. See [Hidden chats](#hidden).":
    "**Conversas ocultas com celulares por perto**: enquanto as conversas ocultas estão abertas, ou recebem fechadas, elas chegam ao celular de um contato por perto por Bluetooth, Wi-Fi Aware, Wi-Fi Direct ou na mesma rede Wi-Fi, sem internet, como suas outras conversas. O espaço nunca fica sabendo que um contato oculto está por perto, e nada no ar distingue as mensagens delas das do espaço; outros celulares nunca as levam, e elas nunca vão por LoRa nem por SMS. Veja [Conversas ocultas](#hidden).",
  "**The same Wi-Fi on Sailfish OS**: Erevos on Sailfish OS finds Erevos phones and computers on the same Wi-Fi or a phone's hotspot and talks with them with no internet, as on a computer. See [On Sailfish OS](#sailfish).":
    "**A mesma rede Wi-Fi no Sailfish OS**: o Erevos no Sailfish OS encontra celulares e computadores com Erevos na mesma rede Wi-Fi ou no roteador de um celular e conversa com eles sem internet, como num computador. Veja [No Sailfish OS](#sailfish).",
  "**Downloads stop at 100 MB**: a file, a backup from a server or any other download is read as it comes and stopped as soon as it passes 100 MB, or less where the network's files are smaller, such as 20 MB for Nostr files, so a file server a contact names can no longer fill the phone's memory with an answer without end. A backup on a server comes back up to 100 MB; download a larger one and open it with Restore a backup. See [Backups](#backup).":
    "**Os downloads param em 100 MB**: um arquivo, um backup de um servidor ou qualquer outro download é lido conforme chega e interrompido assim que passa de 100 MB, ou de menos onde os arquivos da rede são menores, como 20 MB para os arquivos do Nostr, então um servidor de arquivos que um contato indica não consegue mais encher a memória do celular com uma resposta sem fim. Um backup num servidor volta até 100 MB; baixe um maior e abra-o com Restaurar um backup. Veja [Backups](#backup).",
  "**Profile pictures on Matrix and XMPP**: contacts and Matrix rooms show their picture in the chat list, and you can set your own on the Matrix and XMPP screens (Choose a photo). Pictures are not encrypted on either network: the server sees them. See [Matrix](#matrix) and [XMPP](#xmpp).":
    "**Fotos de perfil no Matrix e no XMPP**: contatos e salas do Matrix mostram a foto na lista de conversas, e você pode pôr a sua nas telas do Matrix e do XMPP (Escolher uma foto). As fotos não são criptografadas em nenhuma das duas redes: o servidor as vê. Veja [Matrix](#matrix) e [XMPP](#xmpp).",
  "**Run an XMPP group**: a group's admins can set its subject and take people out or bar them, its owner can rename it and make admins, and in a channel the admin sees who is in it and can put them out. See [XMPP](#xmpp).":
    "**Gerenciar um grupo XMPP**: os admins de um grupo definem o assunto e removem ou banem pessoas, o dono o renomeia e faz admins, e num canal o admin vê quem está dentro e pode tirá-lo. Veja [XMPP](#xmpp).",
  "**Check a Matrix device by QR code**: once both sides accept a check, Erevos shows a code for Element (or another Erevos) to photograph, or photographs theirs, as Element does; comparing emoji stays one tap away. See [Matrix](#matrix).":
    "**Verificar um dispositivo Matrix por código QR**: quando os dois lados aceitam uma verificação, o Erevos mostra um código para o Element (ou outro Erevos) fotografar, ou fotografa o deles, como o Element faz; comparar emoji continua a um toque. Veja [Matrix](#matrix).",
  "**Sign in to Matrix with single sign-on** (Android): when your Matrix server signs people in on its own page, as matrix.org does, Sign in with single sign-on opens it in the browser and comes back to Erevos. See [Matrix](#matrix).":
    "**Entrar no Matrix com início de sessão único** (Android): quando o teu servidor Matrix faz entrar as pessoas na própria página, como o matrix.org, «Entrar com login único (SSO)» abre-a no navegador e volta ao Erevos. Ver [Matrix](#matrix).",
  "**A closed space tells of XMPP messages**: on Android, Say a message came under While this space is closed, on the XMPP screen, has a closed space say \"New message\" when something comes on XMPP while another space is open, never what, from whom or in which chat. Off until you choose it. It needs a relay updated for it and an XMPP server that sends notices to apps that are away; the XMPP server then learns the relay's name, and the relay when messages come. See [XMPP](#xmpp).":
    "**Um espaço fechado avisa de mensagens do XMPP**: no Android, “Avisar quando chega mensagem” em “Enquanto este espaço está fechado”, na tela do XMPP, faz um espaço fechado dizer “Nova mensagem” quando chega algo no XMPP enquanto outro espaço está aberto, nunca o quê, de quem ou em qual conversa. Desligado até você escolher. Precisa de um relay atualizado para isso e de um servidor XMPP que envie avisos a apps inativos; o servidor XMPP fica então sabendo o nome do relay, e o relay quando chegam mensagens. Ver [XMPP](#xmpp).",
  "**Linking a computer is clearer**: on a computer, Settings → Data and devices → Linked devices now starts with Link to my phone, with LPHL's relay filled in and Sign in with LPHL under the token, so no token has to be copied from the phone; and it says that the QR code shows once Link to my phone is tapped. See [Linked devices](#devices).":
    "**Conectar um computador ficou mais claro**: no computador, Configurações → Dados e dispositivos → Dispositivos conectados agora começa com “Conectar ao meu celular”, com o relay do LPHL já preenchido e “Entrar com LPHL” embaixo do token, então não é preciso copiar nenhum token do celular; e avisa que o código QR aparece quando você toca em “Conectar ao meu celular”. Veja [Dispositivos conectados](#devices).",
  "**Delete me from everywhere**: Settings → Privacy and security → Delete me from everywhere deletes what the servers keep for the open space (its queues on the relays with the messages in them, what a relay holds for you to send later, files waiting there, invites nobody used), asks the Nostr relays through Tor to forget the keys your chats read on, and stops the space until you tap Start again. Your phone keeps everything. You can also sign out of Matrix and XMPP and delete the Nostr account made here. See [Delete me from everywhere](#forget).": "**Apagar-me de todos os lugares**: Configurações → Privacidade e segurança → Apagar-me de todos os lugares apaga o que os servidores guardam do espaço aberto (as filas dele nos relays com as mensagens dentro, o que um relay guarda para enviar depois, arquivos que esperam lá, convites que ninguém usou), pede pelo Tor aos relays do Nostr que esqueçam as chaves em que suas conversas leem, e para o espaço até você tocar em Iniciar de novo. Seu celular mantém tudo. Você também pode sair do Matrix e do XMPP e apagar a conta Nostr criada aqui. Veja [Apagar-me de todos os lugares](#forget).",
  "**Every relay queue on one list**: the queues a space keeps on the relays are gathered in one place, and the checks fail if a new kind of queue is made without being added there, so Delete me from everywhere cannot leave one behind.": "**Cada fila de relay em uma lista**: as filas que um espaço guarda nos relays ficam reunidas em um só lugar, e as verificações falham se um novo tipo de fila for criado sem entrar lá, para que Apagar-me de todos os lugares não deixe nenhuma para trás.",
  "**Matrix, XMPP and Nostr on a linked computer**: linking a computer can bring this space's Matrix and XMPP accounts and the key of its Nostr chats over too, each signed in there as a new device of its own; for a computer linked already, tap Send the accounts under it on the phone. A Matrix server seldom lets the phone sign the computer in: the computer then asks for the Matrix password once, and the account's keys come from the phone, so no Security Key or check by emoji is needed. See [Linked devices](#devices).":
    "**Matrix, XMPP e Nostr num computador conectado**: ao conectar um computador, dá para levar também as contas Matrix e XMPP deste espaço e a chave das conversas Nostr dele, cada uma entrando lá como um novo dispositivo próprio; para um computador já conectado, toque em “Enviar as contas” embaixo dele no celular. Um servidor Matrix raramente deixa o celular fazer o computador entrar: o computador então pede a senha do Matrix uma vez, e as chaves da conta vêm do celular, então não é preciso chave de segurança nem verificar por emoji. Veja [Dispositivos conectados](#devices).",
  "**Only the SMS**: with Erevos locked, the SMS icon, the widget's SMS button and the notice of a new SMS ask for the password, then open only the SMS. Anything else, and the orange padlock **Unlock everything**, asks for it again, then opens all of Erevos. See [Password lock](#lock).":
    "**Só os SMS**: com o Erevos bloqueado, o ícone de SMS, o botão SMS do widget e o aviso de um SMS novo pedem a senha e depois abrem só os SMS. Todo o resto, inclusive o cadeado laranja **Desbloquear tudo**, pede a senha de novo e depois abre todo o Erevos. Veja [Bloqueio com senha](#lock).",
  "**Nostr chats with a key brought from another app get their messages again**: Erevos reads where that app said your messages arrive, as that app does, instead of its own three relays, fetches the messages kept there and in older lists of the key, and reads a relay again when it stops sending. Before, such a key could show its chats with no past messages and get no new ones. See [Chats with other Nostr apps](#nostr-chats).":
    "**As conversas Nostr com uma chave trazida de outro app voltam a receber suas mensagens**: o Erevos lê onde esse app disse que chegam as suas mensagens, como esse app faz, em vez dos seus três relays próprios, busca as mensagens guardadas ali e nas listas anteriores da chave, e volta a ler um relay quando ele para de enviar. Antes, uma chave assim podia mostrar suas conversas sem mensagens antigas e não receber novas. Veja [Conversas com outros apps Nostr](#nostr-chats).",
};
